import { useRef, useEffect, useCallback, useState, forwardRef, useImperativeHandle } from 'react';

interface StrokePoint {
  x: number;
  y: number;
}

interface Stroke {
  points: StrokePoint[];
  color: string;
  size: number;
}

export interface AnnotateCanvasHandle {
  undo: () => void;
  clear: () => void;
  hasStrokes: () => boolean;
}

interface AnnotateCanvasProps {
  pan: { x: number; y: number };
  zoom: number;
  color: string;
  brushSize: number;
  active: boolean;
  onStrokesChange?: (count: number) => void;
}

const AnnotateCanvas = forwardRef<AnnotateCanvasHandle, AnnotateCanvasProps>(
  ({ pan, zoom, color, brushSize, active, onStrokesChange }, ref) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const strokesRef = useRef<Stroke[]>([]);
    const drawingRef = useRef(false);
    const currentStrokeRef = useRef<Stroke | null>(null);
    const [, forceUpdate] = useState(0);

    const redraw = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (const stroke of strokesRef.current) {
        if (stroke.points.length < 2) continue;
        ctx.strokeStyle = stroke.color;
        ctx.lineWidth = stroke.size * zoom;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.globalCompositeOperation = stroke.color === '#FFFFFF' ? 'destination-out' : 'source-over';

        ctx.beginPath();
        const p0 = stroke.points[0];
        ctx.moveTo(p0.x * zoom + pan.x, p0.y * zoom + pan.y);
        for (let i = 1; i < stroke.points.length; i++) {
          const p = stroke.points[i];
          ctx.lineTo(p.x * zoom + pan.x, p.y * zoom + pan.y);
        }
        ctx.stroke();
      }

      // Draw current stroke in progress
      const cur = currentStrokeRef.current;
      if (cur && cur.points.length >= 2) {
        ctx.strokeStyle = cur.color;
        ctx.lineWidth = cur.size * zoom;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.globalCompositeOperation = cur.color === '#FFFFFF' ? 'destination-out' : 'source-over';

        ctx.beginPath();
        const p0 = cur.points[0];
        ctx.moveTo(p0.x * zoom + pan.x, p0.y * zoom + pan.y);
        for (let i = 1; i < cur.points.length; i++) {
          const p = cur.points[i];
          ctx.lineTo(p.x * zoom + pan.x, p.y * zoom + pan.y);
        }
        ctx.stroke();
      }

      ctx.globalCompositeOperation = 'source-over';
    }, [pan, zoom]);

    // Resize canvas to fill parent
    useEffect(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ro = new ResizeObserver(() => {
        canvas.width = canvas.parentElement?.clientWidth || window.innerWidth;
        canvas.height = canvas.parentElement?.clientHeight || window.innerHeight;
        redraw();
      });
      ro.observe(canvas.parentElement || document.body);
      return () => ro.disconnect();
    }, [redraw]);

    // Redraw when pan/zoom change
    useEffect(() => { redraw(); }, [pan, zoom, redraw]);

    useImperativeHandle(ref, () => ({
      undo: () => {
        strokesRef.current.pop();
        onStrokesChange?.(strokesRef.current.length);
        forceUpdate(c => c + 1);
        redraw();
      },
      clear: () => {
        strokesRef.current = [];
        onStrokesChange?.(0);
        forceUpdate(c => c + 1);
        redraw();
      },
      hasStrokes: () => strokesRef.current.length > 0,
    }));

    const screenToCanvas = useCallback((e: React.MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return { x: 0, y: 0 };
      const sx = e.clientX - rect.left;
      const sy = e.clientY - rect.top;
      return { x: (sx - pan.x) / zoom, y: (sy - pan.y) / zoom };
    }, [pan, zoom]);

    const handleMouseDown = useCallback((e: React.MouseEvent) => {
      if (!active || e.button !== 0) return;
      e.stopPropagation();
      drawingRef.current = true;
      const pt = screenToCanvas(e);
      currentStrokeRef.current = { points: [pt], color, size: brushSize };
    }, [active, color, brushSize, screenToCanvas]);

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
      if (!drawingRef.current || !currentStrokeRef.current) return;
      e.stopPropagation();
      const pt = screenToCanvas(e);
      currentStrokeRef.current.points.push(pt);
      redraw();
    }, [screenToCanvas, redraw]);

    const handleMouseUp = useCallback(() => {
      if (!drawingRef.current || !currentStrokeRef.current) return;
      if (currentStrokeRef.current.points.length >= 2) {
        strokesRef.current.push(currentStrokeRef.current);
        onStrokesChange?.(strokesRef.current.length);
        forceUpdate(c => c + 1);
      }
      currentStrokeRef.current = null;
      drawingRef.current = false;
      redraw();
    }, [redraw, onStrokesChange]);

    const handleMouseLeave = useCallback(() => {
      if (drawingRef.current && currentStrokeRef.current) {
        if (currentStrokeRef.current.points.length >= 2) {
          strokesRef.current.push(currentStrokeRef.current);
          onStrokesChange?.(strokesRef.current.length);
          forceUpdate(c => c + 1);
        }
        currentStrokeRef.current = null;
        drawingRef.current = false;
        redraw();
      }
    }, [redraw, onStrokesChange]);

    return (
      <canvas
        ref={canvasRef}
        className="absolute inset-0 z-20"
        style={{
          pointerEvents: active ? 'auto' : 'none',
          cursor: active ? 'crosshair' : 'default',
        }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
      />
    );
  }
);

AnnotateCanvas.displayName = 'AnnotateCanvas';
export default AnnotateCanvas;

import { useState } from 'react';
import { Eraser, Pencil, Undo2, Trash2, Plus } from 'lucide-react';

const PRESET_COLORS = ['#FA3756', '#333333', '#21B0FF', '#7BD41A'];

interface AnnotatePanelProps {
  color: string;
  size: number;
  onColorChange: (c: string) => void;
  onSizeChange: (s: number) => void;
  onUndo: () => void;
  onClear: () => void;
  canUndo: boolean;
}

export default function AnnotatePanel({ color, size, onColorChange, onSizeChange, onUndo, onClear, canUndo }: AnnotatePanelProps) {
  const [showSlider, setShowSlider] = useState(false);
  const isEraser = color === '#FFFFFF';

  return (
    <div
      className="absolute left-2 top-1/2 z-50"
      style={{ transform: 'translateY(-50%)', pointerEvents: 'auto' }}
      onMouseDown={e => e.stopPropagation()}
    >
      <div className="relative flex items-center">
        {/* Main panel */}
        <div
          className="flex flex-col items-center gap-3 rounded-lg border border-border px-2 py-3"
          style={{ backgroundColor: 'hsla(10, 28%, 93%, 0.75)', backdropFilter: 'blur(8px)' }}
        >
          {/* Color dots */}
          {PRESET_COLORS.map(c => (
            <button
              key={c}
              className="rounded-full transition-all flex-shrink-0"
              style={{
                width: 20,
                height: 20,
                backgroundColor: c,
                boxShadow: color === c && !isEraser ? `0 0 0 2px hsla(10,28%,93%,1), 0 0 0 3.5px ${c}` : 'none',
              }}
              onClick={() => onColorChange(c)}
            />
          ))}

          {/* Custom color */}
          <label
            className="w-5 h-5 rounded-full border border-dashed border-muted-foreground/40 flex items-center justify-center cursor-pointer hover:border-muted-foreground transition-colors relative"
            style={{
              backgroundColor: !isEraser && !PRESET_COLORS.includes(color) ? color : 'transparent',
              boxShadow: !isEraser && !PRESET_COLORS.includes(color) ? `0 0 0 2px hsla(10,28%,93%,1), 0 0 0 3.5px ${color}` : 'none',
            }}
          >
            {(isEraser || PRESET_COLORS.includes(color)) && <Plus size={10} className="text-muted-foreground" />}
            <input
              type="color"
              className="absolute inset-0 opacity-0 cursor-pointer"
              value={!isEraser ? color : '#000000'}
              onChange={e => onColorChange(e.target.value)}
            />
          </label>

          {/* Divider */}
          <div className="w-5 border-t border-border" />

          {/* Eraser */}
          <button
            className={`w-7 h-7 rounded-md flex items-center justify-center transition-colors ${isEraser ? 'bg-accent text-foreground' : 'text-muted-foreground hover:bg-accent/50 hover:text-foreground'}`}
            onClick={() => onColorChange(isEraser ? PRESET_COLORS[0] : '#FFFFFF')}
            title="Eraser"
          >
            <Eraser size={15} strokeWidth={1.5} />
          </button>

          {/* Brush size */}
          <button
            className={`w-7 h-7 rounded-md flex items-center justify-center transition-colors ${showSlider ? 'bg-accent text-foreground' : 'text-muted-foreground hover:bg-accent/50 hover:text-foreground'}`}
            onClick={() => setShowSlider(v => !v)}
            title="Brush size"
          >
            <Pencil size={15} strokeWidth={1.5} />
          </button>

          {/* Divider */}
          <div className="w-5 border-t border-border" />

          {/* Undo */}
          <button
            className={`w-7 h-7 rounded-md flex items-center justify-center transition-colors ${canUndo ? 'text-muted-foreground hover:bg-accent/50 hover:text-foreground' : 'text-muted-foreground/30'}`}
            onClick={onUndo}
            disabled={!canUndo}
            title="Undo"
          >
            <Undo2 size={15} strokeWidth={1.5} />
          </button>

          {/* Clear */}
          <button
            className={`w-7 h-7 rounded-md flex items-center justify-center transition-colors ${canUndo ? 'text-muted-foreground hover:bg-accent/50 hover:text-foreground' : 'text-muted-foreground/30'}`}
            onClick={onClear}
            disabled={!canUndo}
            title="Clear all"
          >
            <Trash2 size={15} strokeWidth={1.5} />
          </button>
        </div>

        {/* Width slider — opens to the right */}
        {showSlider && (
          <div
            className="absolute left-full ml-1 flex items-center gap-2 rounded-lg border border-border px-3 py-2"
            style={{ backgroundColor: 'hsla(10, 28%, 93%, 0.75)', backdropFilter: 'blur(8px)', whiteSpace: 'nowrap' }}
          >
            <input
              type="range"
              min={2}
              max={40}
              value={size}
              onChange={e => onSizeChange(Number(e.target.value))}
              className="w-24 accent-primary"
              style={{ height: 4 }}
            />
            <span className="text-[10px] text-muted-foreground font-mono w-6 text-right">{size}</span>
          </div>
        )}
      </div>
    </div>
  );
}

