import { useState, useRef, useEffect } from 'react';
import { ChevronDown, GitFork } from 'lucide-react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import type { LayoutMode, LayoutDirection, CanvasBackground, CanvasDrawStyle } from '../types';
import StructureTree from './StructureTree';

interface DropdownOption<T> { value: T; label: string }

function DropdownPicker<T extends string>({
  label,
  value,
  options,
  onChange,
  activeHighlight,
  children,
}: {
  label: string;
  value: T;
  options: DropdownOption<T>[];
  onChange: (v: T) => void;
  activeHighlight?: boolean;
  children?: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  const current = options.find(o => o.value === value);

  return (
    <div className="flex items-center gap-1.5">
      <span className="text-[11px] text-muted-foreground font-mono">{label}:</span>
      <div className="relative" ref={ref}>
        <button
          className={`flex items-center gap-1 px-1.5 py-0.5 rounded text-[11px] font-mono transition-colors ${activeHighlight ? 'bg-accent text-accent-foreground' : 'bg-muted/60 hover:bg-muted text-foreground'}`}
          onClick={() => setOpen(!open)}
        >
          {current?.label}
          <ChevronDown size={10} className="text-muted-foreground" />
        </button>
        {open && (
          <div className="absolute bottom-full mb-1 left-0 bg-card border border-border rounded-md shadow-lg overflow-hidden z-50 min-w-[140px]">
            {options.map(opt => (
              <button
                key={opt.value}
                className={`w-full text-left px-3 py-1.5 text-[11px] font-mono transition-colors ${opt.value === value ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/50 text-foreground'}`}
                onClick={() => { onChange(opt.value); if (!children) setOpen(false); }}
              >
                {opt.label}
              </button>
            ))}
            {children && <div className="border-t border-border">{children}</div>}
          </div>
        )}
      </div>
    </div>
  );
}

const CANVAS_BG_OPTIONS: DropdownOption<CanvasBackground>[] = [
  { value: 'whiteboard', label: 'whiteboard' },
  { value: 'corkboard', label: 'corkboard' },
  { value: 'cutting_mat', label: 'cutting mat' },
  { value: 'blackboard', label: 'blackboard' },
  { value: 'wooden_desk', label: 'wooden desk' },
  { value: 'wall', label: 'wall' },
];

const STYLE_OPTIONS: DropdownOption<CanvasDrawStyle>[] = [
  { value: 'default', label: 'default' },
  { value: 'excalidraw', label: 'excalidraw' },
  { value: 'blueprint', label: 'blueprint' },
  { value: 'minimal', label: 'minimal' },
];

const LAYOUT_MODES: DropdownOption<LayoutMode>[] = [
  { value: 'custom', label: 'default (none)' },
  { value: 'hierarchical', label: 'hierarchical' },
  { value: 'adaptive', label: 'adaptive' },
];

const LAYOUT_DIRS: DropdownOption<LayoutDirection>[] = [
  { value: 'topdown', label: 'topdown' },
  { value: 'sideways', label: 'sideways' },
];

function LayoutDropdown() {
  const { state, dispatch } = useCanvasStore();
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  const currentMode = LAYOUT_MODES.find(m => m.value === state.layoutMode) || LAYOUT_MODES[0];

  const handleLayoutModeChange = (mode: LayoutMode) => {
    dispatch({ type: 'SET_LAYOUT_MODE', mode });
    if (mode !== 'custom') {
      dispatch({ type: 'AUTO_LAYOUT' });
    }
  };

  const handleDirChange = (dir: LayoutDirection) => {
    dispatch({ type: 'SET_LAYOUT_DIRECTION', direction: dir });
    if (state.layoutMode !== 'custom') {
      setTimeout(() => dispatch({ type: 'AUTO_LAYOUT' }), 0);
    }
  };

  return (
    <div className="flex items-center gap-1.5">
      <span className="text-[11px] text-muted-foreground font-mono">layout:</span>
      <div className="relative" ref={ref}>
        <button
          className={`flex items-center gap-1 px-1.5 py-0.5 rounded text-[11px] font-mono transition-colors ${state.layoutMode !== 'custom' ? 'bg-accent text-accent-foreground' : 'bg-muted/60 hover:bg-muted text-foreground'}`}
          onClick={() => setOpen(!open)}
        >
          {currentMode.label}
          <ChevronDown size={10} className="text-muted-foreground" />
        </button>
        {open && (
          <div className="absolute bottom-full mb-1 left-0 bg-card border border-border rounded-md shadow-lg overflow-hidden z-50 min-w-[150px]">
            {/* Layout modes */}
            {LAYOUT_MODES.map(opt => (
              <button
                key={opt.value}
                className={`w-full text-left px-3 py-1.5 text-[11px] font-mono transition-colors ${opt.value === state.layoutMode ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/50 text-foreground'}`}
                onClick={() => handleLayoutModeChange(opt.value)}
              >
                {opt.label}
              </button>
            ))}
            {/* Separator + direction toggle */}
            <div className="border-t border-border px-3 py-2">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-mono">direction</span>
              <div className="flex items-center mt-1.5 border border-border rounded-md overflow-hidden">
                {LAYOUT_DIRS.map(d => (
                  <button
                    key={d.value}
                    className={`flex-1 px-2 py-1 text-[11px] font-mono transition-colors ${state.layoutDirection === d.value ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'}`}
                    onClick={() => handleDirChange(d.value)}
                  >
                    {d.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default function BottomBar() {
  const { state, dispatch } = useCanvasStore();
  const [showTree, setShowTree] = useState(false);
  const treeRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!showTree) return;
    const handler = (e: MouseEvent) => {
      if (treeRef.current && !treeRef.current.contains(e.target as Node)) setShowTree(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [showTree]);

  return (
    <div className="h-9 bg-card border-t border-border flex items-center justify-between px-4 shrink-0">
      {/* Left — stats */}
      <span className="text-[11px] text-primary font-mono">
        {state.nodes.length} nodes · {state.edges.length} connections
      </span>

      {/* Right — canvas, style, layout, structure */}
      <div className="flex items-center gap-3">
        {/* Canvas background */}
        <DropdownPicker
          label="canvas"
          value={state.canvasBackground}
          options={CANVAS_BG_OPTIONS}
          onChange={bg => dispatch({ type: 'SET_CANVAS_BACKGROUND', background: bg })}
        />

        {/* Style */}
        <DropdownPicker
          label="style"
          value={state.canvasDrawStyle}
          options={STYLE_OPTIONS}
          onChange={s => dispatch({ type: 'SET_CANVAS_DRAW_STYLE', drawStyle: s })}
        />

        {/* Layout with nested direction */}
        <LayoutDropdown />

        {/* Structure tree button */}
        <div className="relative" ref={treeRef}>
          <button
            className={`flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-mono transition-colors ${showTree ? 'bg-accent text-accent-foreground' : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'}`}
            onClick={() => setShowTree(!showTree)}
          >
            <GitFork size={12} />
            structure tree
          </button>
          {showTree && (
            <div className="absolute bottom-full mb-1 right-0 w-56 bg-card border border-border rounded-lg shadow-lg overflow-hidden z-50">
              <div className="px-3 py-1.5 text-[10px] uppercase tracking-wider text-muted-foreground border-b border-border font-mono">
                structure tree
              </div>
              <StructureTree />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

