import { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import CanvasNode from './CanvasNode';
import EdgeRenderer from './EdgeRenderer';
import NodeContextMenu from './NodeContextMenu';
import TableContextMenu from './TableContextMenu';
import EdgeContextMenu from './EdgeContextMenu';
import TopBar from './TopBar';
import Sidebar from './Sidebar';
import BottomBar from './BottomBar';
import FloatingToolbox from './FloatingToolbox';
import ZoomOverlay from './ZoomOverlay';
import AnnotateCanvas, { type AnnotateCanvasHandle } from './AnnotateCanvas';
import AnnotatePanel from './AnnotatePanel';
import type { CanvasState, ConnectingState, CanvasBackground, ShapeType } from '../types';
import { DEFAULT_NODE_STYLE } from '../types';

export default function Canvas() {
  const { state, dispatch, getHiddenNodeIds, connectNodes, createQuickFlowNode } = useCanvasStore();
  const [panning, setPanning] = useState(false);
  const panStart = useRef({ x: 0, y: 0, px: 0, py: 0 });
  const [nodeCtx, setNodeCtx] = useState<{ id: string; pos: { x: number; y: number } } | null>(null);
  const [tableCtx, setTableCtx] = useState<{ id: string; pos: { x: number; y: number }; cell?: { r: number; c: number } } | null>(null);
  const [edgeCtx, setEdgeCtx] = useState<{ id: string; pos: { x: number; y: number } } | null>(null);

  // Drag-to-connect state
  const [connecting, setConnecting] = useState<ConnectingState | null>(null);
  const [connectMouse, setConnectMouse] = useState<{ x: number; y: number } | null>(null);
  const [connectTargetId, setConnectTargetId] = useState<string | null>(null);
  const connectDragged = useRef(false);

  // Box selection
  const [boxSelect, setBoxSelect] = useState<{ startX: number; startY: number; curX: number; curY: number } | null>(null);
  const canvasRef = useRef<HTMLDivElement>(null);
  const annotateRef = useRef<AnnotateCanvasHandle>(null);
  const [annotateColor, setAnnotateColor] = useState('#FA3756');
  const [annotateSize, setAnnotateSize] = useState(10);
  const [annotateStrokeCount, setAnnotateStrokeCount] = useState(0);

  // Undo/redo
  const historyRef = useRef<CanvasState[]>([]);
  const futureRef = useRef<CanvasState[]>([]);
  const prevStateRef = useRef<string>('');

  const hiddenIds = useMemo(() => getHiddenNodeIds(), [getHiddenNodeIds]);
  const visibleNodes = useMemo(() => state.nodes.filter(n => !hiddenIds.has(n.id)), [state.nodes, hiddenIds]);
  const visibleEdges = useMemo(() => state.edges.filter(e => !hiddenIds.has(e.fromNodeId) && !hiddenIds.has(e.toNodeId)), [state.edges, hiddenIds]);

  useEffect(() => {
    const serialized = JSON.stringify({ nodes: state.nodes, edges: state.edges });
    if (serialized !== prevStateRef.current && prevStateRef.current) {
      historyRef.current.push(JSON.parse(prevStateRef.current));
      if (historyRef.current.length > 50) historyRef.current.shift();
      futureRef.current = [];
    }
    prevStateRef.current = serialized;
  }, [state.nodes, state.edges]);

  const undo = useCallback(() => {
    const prev = historyRef.current.pop();
    if (!prev) return;
    futureRef.current.push({ ...state });
    dispatch({ type: 'RESTORE', state: { ...prev, pan: state.pan, zoom: state.zoom, selectedNodeId: null, selectedNodeIds: [], selectedEdgeId: null, editingNodeId: null, editingEdgeId: null, tool: state.tool, mode: state.mode, layoutMode: state.layoutMode, layoutDirection: state.layoutDirection, canvasBackground: state.canvasBackground, canvasDrawStyle: state.canvasDrawStyle, bgConfig: state.bgConfig, boardTitle: state.boardTitle } });
  }, [state, dispatch]);

  const redo = useCallback(() => {
    const next = futureRef.current.pop();
    if (!next) return;
    historyRef.current.push({ ...state });
    dispatch({ type: 'RESTORE', state: { ...next, pan: state.pan, zoom: state.zoom, selectedNodeId: null, selectedNodeIds: [], selectedEdgeId: null, editingNodeId: null, editingEdgeId: null, tool: state.tool, mode: state.mode, layoutMode: state.layoutMode, layoutDirection: state.layoutDirection, canvasBackground: state.canvasBackground, canvasDrawStyle: state.canvasDrawStyle, bgConfig: state.bgConfig, boardTitle: state.boardTitle } });
  }, [state, dispatch]);

  // Connecting drag handlers
  const handleStartConnect = useCallback((cs: ConnectingState) => {
    setConnecting(cs);
    connectDragged.current = false;
  }, []);

  useEffect(() => {
    if (!connecting) return;

    const onMove = (e: MouseEvent) => {
      connectDragged.current = true;
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;
      // Convert screen coords to canvas coords
      const cx = (e.clientX - rect.left - state.pan.x) / state.zoom;
      const cy = (e.clientY - rect.top - state.pan.y) / state.zoom;
      setConnectMouse({ x: cx, y: cy });

      // Hit test against visible nodes
      let hitId: string | null = null;
      for (const n of visibleNodes) {
        if (n.id === connecting.fromNodeId) continue;
        if (cx >= n.x && cx <= n.x + n.width && cy >= n.y && cy <= n.y + n.height) {
          hitId = n.id;
          break;
        }
      }
      setConnectTargetId(hitId);
    };

    const onUp = () => {
      if (connectDragged.current && connectTargetId) {
        // Connect to existing node
        connectNodes(connecting.fromNodeId, connectTargetId);
      } else if (!connectDragged.current) {
        // Simple click — create new node (quickflow)
        createQuickFlowNode(connecting.fromNodeId, connecting.direction);
      }
      setConnecting(null);
      setConnectMouse(null);
      setConnectTargetId(null);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
  }, [connecting, connectTargetId, state.pan, state.zoom, visibleNodes, connectNodes, createQuickFlowNode]);

  // Mouse down on canvas
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0) return;

    if (state.tool === 'pan') {
      setPanning(true);
      panStart.current = { x: e.clientX, y: e.clientY, px: state.pan.x, py: state.pan.y };
      return;
    }

    if (state.tool === 'select') {
      dispatch({ type: 'SELECT_NODE', id: null });
      dispatch({ type: 'SELECT_EDGE', id: null });
      dispatch({ type: 'SET_EDITING', id: null });
      dispatch({ type: 'SET_EDITING_EDGE', id: null });

      // In select mode, drag always starts box selection (not panning)
      const rect = canvasRef.current?.getBoundingClientRect();
      if (rect) {
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        setBoxSelect({ startX: x, startY: y, curX: x, curY: y });
      }
    }
  }, [state.pan, state.tool, dispatch]);

  useEffect(() => {
    if (!panning && !boxSelect) return;

    const onMove = (e: MouseEvent) => {
      if (panning) {
        dispatch({ type: 'SET_PAN', pan: {
          x: panStart.current.px + (e.clientX - panStart.current.x),
          y: panStart.current.py + (e.clientY - panStart.current.y),
        }});
      }
      if (boxSelect) {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (rect) {
          setBoxSelect(prev => prev ? { ...prev, curX: e.clientX - rect.left, curY: e.clientY - rect.top } : null);
        }
      }
    };

    const onUp = () => {
      if (boxSelect) {
        const { startX, startY, curX, curY } = boxSelect;
        const bx1 = Math.min(startX, curX);
        const by1 = Math.min(startY, curY);
        const bx2 = Math.max(startX, curX);
        const by2 = Math.max(startY, curY);

        const ids = visibleNodes.filter(n => {
          const nx = n.x * state.zoom + state.pan.x;
          const ny = n.y * state.zoom + state.pan.y;
          const nw = n.width * state.zoom;
          const nh = n.height * state.zoom;
          return nx + nw > bx1 && nx < bx2 && ny + nh > by1 && ny < by2;
        }).map(n => n.id);

        if (ids.length > 0) {
          dispatch({ type: 'SELECT_NODES', ids });
        }
        setBoxSelect(null);
      }
      setPanning(false);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
  }, [panning, boxSelect, dispatch, visibleNodes, state.zoom, state.pan]);

  // Zoom
  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.05 : 0.05;
    dispatch({ type: 'SET_ZOOM', zoom: state.zoom + delta });
  }, [state.zoom, dispatch]);

  // Edge double-click to edit label
  const handleEdgeDoubleClick = useCallback((id: string) => {
    dispatch({ type: 'SELECT_EDGE', id });
    dispatch({ type: 'UPDATE_EDGE_STYLE', id, style: { showMidLabel: true } });
    dispatch({ type: 'SET_EDITING_EDGE', id });
  }, [dispatch]);

  const handleEdgeLabelChange = useCallback((id: string, label: string) => {
    dispatch({ type: 'UPDATE_EDGE_STYLE', id, style: { midLabel: label, showMidLabel: label.length > 0 } });
  }, [dispatch]);

  const handleEdgeLabelBlur = useCallback(() => {
    dispatch({ type: 'SET_EDITING_EDGE', id: null });
  }, [dispatch]);

  // Keyboard
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (state.editingNodeId || state.editingEdgeId) return;
      if ((e.key === 'Delete' || e.key === 'Backspace')) {
        if (state.selectedNodeIds.length > 0) {
          for (const id of state.selectedNodeIds) {
            dispatch({ type: 'DELETE_NODE', id });
          }
        }
        if (state.selectedEdgeId) {
          dispatch({ type: 'DELETE_EDGE', id: state.selectedEdgeId });
        }
      }
      if (e.key === 'Escape') {
        dispatch({ type: 'SELECT_NODE', id: null });
        dispatch({ type: 'SELECT_EDGE', id: null });
        dispatch({ type: 'SET_EDITING_EDGE', id: null });
        setNodeCtx(null);
        setTableCtx(null);
        setEdgeCtx(null);
      }
      if (e.key === 'z' && (e.ctrlKey || e.metaKey) && !e.shiftKey) { e.preventDefault(); undo(); }
      if (e.key === 'z' && (e.ctrlKey || e.metaKey) && e.shiftKey) { e.preventDefault(); redo(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [state.selectedNodeIds, state.selectedEdgeId, state.editingNodeId, state.editingEdgeId, dispatch, undo, redo]);

  // Paste image handler
  const IMAGE_TYPES = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/avif', 'image/svg+xml'];

  const createImageNode = useCallback((file: File, screenX?: number, screenY?: number) => {
    const url = URL.createObjectURL(file);
    const img = new window.Image();
    img.onload = () => {
      const maxW = 400;
      const scale = img.naturalWidth > maxW ? maxW / img.naturalWidth : 1;
      const w = Math.round(img.naturalWidth * scale);
      const h = Math.round(img.naturalHeight * scale);

      const rect = canvasRef.current?.getBoundingClientRect();
      let cx: number, cy: number;
      if (screenX !== undefined && screenY !== undefined && rect) {
        cx = (screenX - rect.left - state.pan.x) / state.zoom;
        cy = (screenY - rect.top - state.pan.y) / state.zoom;
      } else {
        cx = (-state.pan.x + window.innerWidth / 2) / state.zoom - w / 2;
        cy = (-state.pan.y + window.innerHeight / 2) / state.zoom - h / 2;
      }

      const node = {
        id: `node_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        x: cx, y: cy, width: w, height: h,
        label: file.name.replace(/\.[^.]+$/, ''),
        shape: 'image_embed' as ShapeType,
        polygonEdges: 6,
        style: { ...DEFAULT_NODE_STYLE, borderWidth: 0, fillColor: '#F0F0F0' as const },
        quickflowEnabled: true,
        collapsed: false,
        hyperlink: '',
        imageUrl: url,
        imageUrls: [],
        orientation: 'portrait' as const,
        photoStripCount: 3,
        parentId: null,
        childIds: [],
        zIndex: state.nodes.length + 1,
      };
      dispatch({ type: 'ADD_NODE', node });
      dispatch({ type: 'SELECT_NODE', id: node.id });
    };
    img.src = url;
  }, [state.pan, state.zoom, state.nodes.length, dispatch]);

  // Also handle pasting image URLs from clipboard
  useEffect(() => {
    const onPaste = (e: ClipboardEvent) => {
      // Don't handle paste when editing text
      if (state.editingNodeId || state.editingEdgeId) return;

      const items = e.clipboardData?.items;
      if (!items) return;

      // Check for pasted image files
      for (const item of items) {
        if (IMAGE_TYPES.includes(item.type)) {
          e.preventDefault();
          const file = item.getAsFile();
          if (file) createImageNode(file);
          return;
        }
      }

      // Check for pasted image URL text
      const text = e.clipboardData?.getData('text/plain')?.trim();
      if (text && /^https?:\/\/.+\.(png|jpe?g|webp|avif|svg)(\?.*)?$/i.test(text)) {
        e.preventDefault();
        const img = new window.Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
          const maxW = 400;
          const scale = img.naturalWidth > maxW ? maxW / img.naturalWidth : 1;
          const w = Math.round(img.naturalWidth * scale);
          const h = Math.round(img.naturalHeight * scale);
          const cx = (-state.pan.x + window.innerWidth / 2) / state.zoom - w / 2;
          const cy = (-state.pan.y + window.innerHeight / 2) / state.zoom - h / 2;

          const node = {
            id: `node_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
            x: cx, y: cy, width: w, height: h,
            label: '',
            shape: 'image_embed' as ShapeType,
            polygonEdges: 6,
            style: { ...DEFAULT_NODE_STYLE, borderWidth: 0, fillColor: '#F0F0F0' as const },
            quickflowEnabled: true,
            collapsed: false,
            hyperlink: '',
            imageUrl: text,
            imageUrls: [],
            orientation: 'portrait' as const,
            photoStripCount: 3,
            parentId: null,
            childIds: [],
            zIndex: state.nodes.length + 1,
          };
          dispatch({ type: 'ADD_NODE', node });
          dispatch({ type: 'SELECT_NODE', id: node.id });
        };
        img.onerror = () => {
          // Not a valid image URL, ignore
        };
        img.src = text;
      }
    };
    window.addEventListener('paste', onPaste);
    return () => window.removeEventListener('paste', onPaste);
  }, [state.editingNodeId, state.editingEdgeId, state.pan, state.zoom, state.nodes.length, dispatch, createImageNode]);

  // Drag & drop image files
  const [dragOver, setDragOver] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    const hasImage = Array.from(e.dataTransfer.types).includes('Files');
    if (hasImage) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'copy';
      setDragOver(true);
    }
  }, []);

  const handleDragLeave = useCallback(() => setDragOver(false), []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const files = Array.from(e.dataTransfer.files);
    let offset = 0;
    for (const file of files) {
      if (IMAGE_TYPES.includes(file.type)) {
        createImageNode(file, e.clientX + offset, e.clientY + offset);
        offset += 30;
      }
    }
  }, [createImageNode]);

  const handleNodeContextMenu = (e: React.MouseEvent, id: string) => {
    const node = state.nodes.find(n => n.id === id);
    dispatch({ type: 'SELECT_NODE', id });
    setEdgeCtx(null);
    if (node?.shape === 'table_grid' && node.tableData) {
      // Table nodes get their own context menu — cell info will come from the TableNode component
      setNodeCtx(null);
      setTableCtx({ id, pos: { x: e.clientX, y: e.clientY } });
    } else {
      setTableCtx(null);
      setNodeCtx({ id, pos: { x: e.clientX, y: e.clientY } });
    }
  };

  const handleTableCellContextMenu = (nodeId: string, r: number, c: number, e: React.MouseEvent) => {
    dispatch({ type: 'SELECT_NODE', id: nodeId });
    setNodeCtx(null);
    setEdgeCtx(null);
    setTableCtx({ id: nodeId, pos: { x: e.clientX, y: e.clientY }, cell: { r, c } });
  };

  const handleEdgeContextMenu = (e: React.MouseEvent, id: string) => {
    dispatch({ type: 'SELECT_EDGE', id });
    setNodeCtx(null);
    setTableCtx(null);
    setEdgeCtx({ id, pos: { x: e.clientX, y: e.clientY } });
  };

  const canvasCursor = connecting ? 'crosshair' : state.tool === 'annotate' ? 'crosshair' : state.tool === 'pan' ? (panning ? 'grabbing' : 'grab') : (panning ? 'grabbing' : 'default');

  const canvasBgStyle = useMemo(() => {
    const bg = state.canvasBackground;
    const z = state.zoom;
    const base = {
      backgroundPosition: `${state.pan.x}px ${state.pan.y}px`,
    };
    switch (bg) {
      case 'corkboard': return { ...base, backgroundImage: `url('https://images.fillout.com/orgid-704952/flowpublicid-xkqm3ivkhg/widgetid-default/7QcYCr2rn753iUnJTksSQe/pasted-image-1784897069173-0usgywyv.png')`, backgroundSize: `${300 * z}px ${300 * z}px`, backgroundRepeat: 'repeat', backgroundColor: '#c4a775' };
      case 'cutting_mat': return {
        ...base,
        backgroundImage: `
          linear-gradient(rgba(255,255,255,0.08) 1px, transparent 1px),
          linear-gradient(90deg, rgba(255,255,255,0.08) 1px, transparent 1px)
        `,
        backgroundSize: `${24 * z}px ${24 * z}px`,
        backgroundColor: '#2d8659',
      };
      case 'blackboard': return {
        ...base,
        backgroundImage: 'none',
        backgroundColor: '#2a2a2a',
      };
      case 'wooden_desk': return {
        ...base,
        backgroundImage: `repeating-linear-gradient(90deg, rgba(0,0,0,0.03) 0px, rgba(0,0,0,0.03) 1px, transparent 1px, transparent ${12 * z}px)`,
        backgroundSize: `${12 * z}px ${12 * z}px`,
        backgroundColor: '#b08d6b',
      };
      case 'wall': return {
        ...base,
        backgroundImage: 'none',
        backgroundColor: '#e8e0d4',
      };
      default: {
        const cfg = state.bgConfig;
        const gs = cfg.gridSize * z;
        const lc = cfg.lineColor;
        switch (cfg.pattern) {
          case 'blank':
            return { ...base, backgroundImage: 'none', backgroundColor: cfg.color };
          case 'grid':
            return {
              ...base,
              backgroundImage: `linear-gradient(${lc}40 1px, transparent 1px), linear-gradient(90deg, ${lc}40 1px, transparent 1px)`,
              backgroundSize: `${gs}px ${gs}px`,
              backgroundColor: cfg.color,
            };
          case 'lined':
            return {
              ...base,
              backgroundImage: `linear-gradient(${lc}35 1px, transparent 1px)`,
              backgroundSize: `${gs}px ${gs}px`,
              backgroundColor: cfg.color,
            };
          case 'dotted':
          default:
            return {
              ...base,
              backgroundImage: `radial-gradient(circle, ${lc} 1.2px, transparent 1.2px)`,
              backgroundSize: `${gs}px ${gs}px`,
              backgroundColor: cfg.color,
            };
        }
      }
    }
  }, [state.canvasBackground, state.bgConfig, state.zoom, state.pan.x, state.pan.y]);

  const boxRect = boxSelect ? {
    left: Math.min(boxSelect.startX, boxSelect.curX),
    top: Math.min(boxSelect.startY, boxSelect.curY),
    width: Math.abs(boxSelect.curX - boxSelect.startX),
    height: Math.abs(boxSelect.curY - boxSelect.startY),
  } : null;

  // Compute connect preview elbow path
  const connectPreviewPath = useMemo(() => {
    if (!connecting || !connectMouse) return null;
    const fromNode = state.nodes.find(n => n.id === connecting.fromNodeId);
    if (!fromNode) return null;
    const fcx = fromNode.x + fromNode.width / 2;
    const fcy = fromNode.y + fromNode.height / 2;
    let sx = fcx, sy = fcy;
    const dir = connecting.direction;
    if (dir === 'up') { sx = fcx; sy = fromNode.y; }
    else if (dir === 'down') { sx = fcx; sy = fromNode.y + fromNode.height; }
    else if (dir === 'left') { sx = fromNode.x; sy = fcy; }
    else if (dir === 'right') { sx = fromNode.x + fromNode.width; sy = fcy; }

    const ex = connectMouse.x, ey = connectMouse.y;
    const isVert = dir === 'up' || dir === 'down';

    // Build elbow points
    let pts: { x: number; y: number }[];
    if (isVert) {
      const midY = (sy + ey) / 2;
      pts = [{ x: sx, y: sy }, { x: sx, y: midY }, { x: ex, y: midY }, { x: ex, y: ey }];
    } else {
      const midX = (sx + ex) / 2;
      pts = [{ x: sx, y: sy }, { x: midX, y: sy }, { x: midX, y: ey }, { x: ex, y: ey }];
    }

    // Rounded path
    const r = 12;
    const segs: string[] = [`M ${pts[0].x} ${pts[0].y}`];
    for (let i = 1; i < pts.length - 1; i++) {
      const prev = pts[i - 1], curr = pts[i], next = pts[i + 1];
      const dx1 = prev.x - curr.x, dy1 = prev.y - curr.y;
      const dx2 = next.x - curr.x, dy2 = next.y - curr.y;
      const len1 = Math.sqrt(dx1 * dx1 + dy1 * dy1);
      const len2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);
      if (len1 === 0 || len2 === 0) { segs.push(`L ${curr.x} ${curr.y}`); continue; }
      const maxR = Math.min(r, len1 / 2, len2 / 2);
      const s1x = curr.x + (dx1 / len1) * maxR, s1y = curr.y + (dy1 / len1) * maxR;
      const e1x = curr.x + (dx2 / len2) * maxR, e1y = curr.y + (dy2 / len2) * maxR;
      segs.push(`L ${s1x} ${s1y}`);
      segs.push(`Q ${curr.x} ${curr.y} ${e1x} ${e1y}`);
    }
    segs.push(`L ${pts[pts.length - 1].x} ${pts[pts.length - 1].y}`);
    return segs.join(' ');
  }, [connecting, connectMouse, state.nodes]);

  return (
    <div className="w-screen h-screen flex flex-col overflow-hidden select-none">
      <TopBar onUndo={undo} onRedo={redo} canUndo={historyRef.current.length > 0} canRedo={futureRef.current.length > 0} />

      <div className="flex flex-1 min-h-0">
        <Sidebar />

        {/* Canvas area */}
        <div
          ref={canvasRef}
          className="flex-1 relative overflow-hidden"
          style={{
            ...canvasBgStyle,
            cursor: canvasCursor,
          }}
          onMouseDown={handleMouseDown}
          onWheel={handleWheel}
          onContextMenu={e => e.preventDefault()}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          <FloatingToolbox />

          {/* Annotate overlay */}
          <AnnotateCanvas
            ref={annotateRef}
            pan={state.pan}
            zoom={state.zoom}
            color={annotateColor}
            brushSize={annotateSize}
            active={state.tool === 'annotate'}
            onStrokesChange={setAnnotateStrokeCount}
          />

          {/* Annotate crayon panel — bottom, from sidebar trigger */}
          {state.tool === 'annotate' && (
            <AnnotatePanel
              color={annotateColor}
              size={annotateSize}
              onColorChange={setAnnotateColor}
              onSizeChange={setAnnotateSize}
              onUndo={() => annotateRef.current?.undo()}
              onClear={() => annotateRef.current?.clear()}
              canUndo={annotateStrokeCount > 0}
            />
          )}

          {boxRect && (
            <div className="absolute border border-primary/60 bg-primary/10 pointer-events-none z-30" style={boxRect} />
          )}

          {/* Transform layer */}
          <div style={{
            transform: `translate(${state.pan.x}px, ${state.pan.y}px) scale(${state.zoom})`,
            transformOrigin: '0 0',
            position: 'absolute', top: 0, left: 0,
            width: '1px', height: '1px',
          }}>
            {/* SVG for edges + connect preview */}
            <svg className="absolute" style={{ top: 0, left: 0, width: '200000px', height: '200000px', transform: 'translate(-100000px, -100000px)', pointerEvents: 'none', overflow: 'visible' }}>
              <defs>
                <filter id="pencil-filter">
                  <feTurbulence type="turbulence" baseFrequency="0.03" numOctaves="4" result="noise" />
                  <feDisplacementMap in="SourceGraphic" in2="noise" scale="1.5" />
                </filter>
              </defs>
              <g style={{ transform: 'translate(100000px, 100000px)', pointerEvents: 'all' }}>
                {visibleEdges.map(edge => {
                  const fromNode = state.nodes.find(n => n.id === edge.fromNodeId);
                  const toNode = state.nodes.find(n => n.id === edge.toNodeId);
                  if (!fromNode || !toNode) return null;
                  return (
                    <EdgeRenderer
                      key={edge.id}
                      edge={edge}
                      fromNode={fromNode}
                      toNode={toNode}
                      isSelected={state.selectedEdgeId === edge.id}
                      isEditingLabel={state.editingEdgeId === edge.id}
                      onSelect={(id) => dispatch({ type: 'SELECT_EDGE', id })}
                      onContextMenu={handleEdgeContextMenu}
                      onDoubleClick={handleEdgeDoubleClick}
                      onLabelChange={handleEdgeLabelChange}
                      onLabelBlur={handleEdgeLabelBlur}
                    />
                  );
                })}

                {/* Connect preview elbow */}
                {connectPreviewPath && (
                  <g>
                    <defs>
                      <marker id="connect-preview-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
                        <path d="M 0 0 L 10 5 L 0 10 z" fill="#9ca3af" />
                      </marker>
                    </defs>
                    <path
                      d={connectPreviewPath}
                      fill="none" stroke="#9ca3af" strokeWidth={2.5}
                      strokeLinecap="round" strokeLinejoin="round"
                      markerEnd="url(#connect-preview-arrow)"
                    />
                  </g>
                )}
              </g>
            </svg>

            {/* Nodes */}
            {visibleNodes.map(node => (
              <CanvasNode
                key={node.id}
                node={node}
                isSelected={state.selectedNodeIds.includes(node.id)}
                isEditing={state.editingNodeId === node.id}
                zoom={state.zoom}
                isConnectTarget={connectTargetId === node.id}
                onContextMenu={handleNodeContextMenu}
                onStartConnect={handleStartConnect}
                onTableCellContextMenu={handleTableCellContextMenu}
              />
            ))}
          </div>

          {nodeCtx && <NodeContextMenu nodeId={nodeCtx.id} position={nodeCtx.pos} onClose={() => setNodeCtx(null)} />}
          {tableCtx && <TableContextMenu nodeId={tableCtx.id} position={tableCtx.pos} contextCell={tableCtx.cell} onClose={() => setTableCtx(null)} />}
          {edgeCtx && <EdgeContextMenu edgeId={edgeCtx.id} position={edgeCtx.pos} onClose={() => setEdgeCtx(null)} />}

          {/* Drop overlay */}
          {dragOver && (
            <div className="absolute inset-0 z-50 pointer-events-none flex items-center justify-center bg-primary/5 border-2 border-dashed border-primary/40 rounded-lg">
              <div className="bg-card/90 backdrop-blur-sm px-6 py-3 rounded-xl shadow-lg border border-border">
                <span className="text-sm font-mono text-foreground">drop image here</span>
              </div>
            </div>
          )}

          {/* Zoom overlay — bottom-right */}
          <ZoomOverlay />
        </div>
      </div>

      <BottomBar />
    </div>
  );
}

