import { useRef, useState, useEffect, useCallback } from 'react';
import type { CanvasNode as NodeType, ConnectingState } from '../types';
import { useCanvasStore } from '../hooks/useCanvasStore';
import ShapeRenderer from './ShapeRenderer';
import TableNode from './TableNode';
import QuickFlowHandles from './QuickFlowHandles';
import ResizeHandles from './ResizeHandles';

interface Props {
  node: NodeType;
  isSelected: boolean;
  isEditing: boolean;
  zoom: number;
  isConnectTarget: boolean;
  onContextMenu: (e: React.MouseEvent, id: string) => void;
  onStartConnect: (state: ConnectingState) => void;
  onTableCellContextMenu?: (nodeId: string, r: number, c: number, e: React.MouseEvent) => void;
}

export default function CanvasNode({ node, isSelected, isEditing, zoom, isConnectTarget, onContextMenu, onStartConnect, onTableCellContextMenu }: Props) {
  const { dispatch, createQuickFlowNode } = useCanvasStore();
  const [dragging, setDragging] = useState(false);
  const dragStart = useRef({ x: 0, y: 0, nx: 0, ny: 0 });
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (isEditing) return;
    e.stopPropagation();
    if (e.shiftKey) {
      dispatch({ type: 'TOGGLE_SELECT_NODE', id: node.id });
    } else {
      dispatch({ type: 'SELECT_NODE', id: node.id });
    }
    setDragging(true);
    dragStart.current = { x: e.clientX, y: e.clientY, nx: node.x, ny: node.y };
  }, [node.id, node.x, node.y, isEditing, dispatch]);

  useEffect(() => {
    if (!dragging) return;
    const onMove = (e: MouseEvent) => {
      const dx = (e.clientX - dragStart.current.x) / zoom;
      const dy = (e.clientY - dragStart.current.y) / zoom;
      dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { x: dragStart.current.nx + dx, y: dragStart.current.ny + dy } });
    };
    const onUp = () => setDragging(false);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
  }, [dragging, node.id, zoom, dispatch]);

  const isTableShape = node.shape === 'table_grid' && node.tableData;

  const handleDoubleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isTableShape) return;
    dispatch({ type: 'SET_EDITING', id: node.id });
  };

  const pad = node.style?.padding ?? 8;
  const isPhotoShape = node.shape === 'polaroid' || node.shape === 'film_strip' || node.shape === 'photo_strip' || node.shape === 'image_embed';
  const photoTextH = node.shape === 'polaroid'
    ? (node.orientation === 'landscape' ? node.width * 0.22 : Math.min(node.width, node.height) * 0.06 * 2.5)
    : node.shape === 'photo_strip' ? node.height * 0.11
    : node.shape === 'image_embed' ? 0
    : 28;

  return (
    <div
      className="absolute group"
      data-node-id={node.id}
      style={{
        left: node.x, top: node.y, width: node.width, height: node.height,
        cursor: isEditing ? 'text' : 'grab',
        zIndex: isSelected ? 1000 + node.zIndex : node.zIndex,
        opacity: node.style?.opacity ?? 1,
      }}
      onMouseDown={handleMouseDown}
      onDoubleClick={handleDoubleClick}
      onContextMenu={(e) => { e.preventDefault(); e.stopPropagation(); onContextMenu(e, node.id); }}
    >
      <ShapeRenderer
        shape={node.shape}
        width={node.width}
        height={node.height}
        style={node.style}
        polygonEdges={node.polygonEdges}
        imageUrl={node.imageUrl}
        imageUrls={node.imageUrls}
        orientation={node.orientation}
        photoStripCount={node.photoStripCount}
        onImageAreaClick={(slotIndex?: number) => {
          const input = document.createElement('input');
          input.type = 'file';
          input.accept = 'image/*';
          input.onchange = (ev) => {
            const file = (ev.target as HTMLInputElement).files?.[0];
            if (file) {
              const url = URL.createObjectURL(file);
              if (node.shape === 'photo_strip' && slotIndex !== undefined) {
                const urls = [...(node.imageUrls || [])];
                while (urls.length <= slotIndex) urls.push('');
                urls[slotIndex] = url;
                dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { imageUrls: urls } });
              } else {
                dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { imageUrl: url } });
              }
            }
          };
          input.click();
        }}
      />

      {/* Table overlay */}
      {isTableShape && (
        <TableNode
          nodeId={node.id}
          width={node.width}
          height={node.height}
          tableData={node.tableData!}
          style={node.style}
          isSelected={isSelected}
          onCellContextMenu={(r, c, e) => onTableCellContextMenu?.(node.id, r, c, e)}
        />
      )}

      {/* Connect target highlight */}
      {isConnectTarget && (
        <div className="absolute inset-[-3px] pointer-events-none" style={{
          border: '2.5px solid #6366f1',
          borderRadius: node.shape === 'circle' || node.shape === 'oval' ? '50%' : ((node.style?.borderRadius ?? 8) + 3),
        }} />
      )}

      {/* Label */}
      {isTableShape ? null : isPhotoShape ? (
        <div className="absolute left-0 right-0 bottom-0 flex items-center justify-center pointer-events-none" style={{ height: photoTextH, padding: `0 ${pad}px`, textAlign: node.style?.textAlign ?? 'center' }}>
          {isEditing ? (
            <textarea
              ref={inputRef}
              className="w-full h-full bg-transparent border-none outline-none resize-none text-center pointer-events-auto"
              style={{ fontSize: node.style?.fontSize ?? 12, fontWeight: node.style?.fontWeight ?? 'normal', textAlign: node.style?.textAlign ?? 'center', color: '#1a1a2e' }}
              value={node.label}
              onChange={e => dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { label: e.target.value } })}
              onBlur={() => dispatch({ type: 'SET_EDITING', id: null })}
              onKeyDown={e => { if (e.key === 'Escape' || (e.key === 'Enter' && !e.shiftKey)) { e.preventDefault(); dispatch({ type: 'SET_EDITING', id: null }); } }}
              onMouseDown={e => e.stopPropagation()}
            />
          ) : (
            <span className="select-none" style={{ fontSize: node.style?.fontSize ?? 12, fontWeight: node.style?.fontWeight ?? 'normal', color: '#555' }}>
              {node.label || (isSelected ? '' : '')}
            </span>
          )}
        </div>
      ) : (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none" style={{ padding: pad, textAlign: node.style?.textAlign ?? 'center' }}>
          {isEditing ? (
            <textarea
              ref={inputRef}
              className="w-full h-full bg-transparent border-none outline-none resize-none text-center pointer-events-auto"
              style={{ fontSize: node.style?.fontSize ?? 14, fontWeight: node.style?.fontWeight ?? 'normal', textAlign: node.style?.textAlign ?? 'center', color: '#1a1a2e' }}
              value={node.label}
              onChange={e => dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { label: e.target.value } })}
              onBlur={() => dispatch({ type: 'SET_EDITING', id: null })}
              onKeyDown={e => { if (e.key === 'Escape' || (e.key === 'Enter' && !e.shiftKey)) { e.preventDefault(); dispatch({ type: 'SET_EDITING', id: null }); } }}
              onMouseDown={e => e.stopPropagation()}
            />
          ) : (
            <span className="select-none text-foreground" style={{ fontSize: node.style?.fontSize ?? 14, fontWeight: node.style?.fontWeight ?? 'normal' }}>
              {node.label || (isSelected ? '' : 'double-click to edit')}
            </span>
          )}
        </div>
      )}

      {/* Selection outline */}
      {isSelected && !isConnectTarget && (
        <div className="absolute inset-0 pointer-events-none" style={{
          border: '2px solid #6366f1',
          borderRadius: node.shape === 'circle' || node.shape === 'oval' ? '50%' : (node.style?.borderRadius ?? 8),
        }} />
      )}

      {/* Collapse indicator */}
      {node.collapsed && node.childIds.length > 0 && (
        <div className="absolute -bottom-3 left-1/2 -translate-x-1/2 bg-primary text-primary-foreground text-[8px] px-1.5 py-0.5 rounded-full pointer-events-none">
          {node.childIds.length} hidden
        </div>
      )}

      {isSelected && !isEditing && node.quickflowEnabled && (
        <QuickFlowHandles
          nodeId={node.id}
          width={node.width}
          height={node.height}
          onStartConnect={onStartConnect}
          onQuickCreate={(id, dir) => createQuickFlowNode(id, dir)}
        />
      )}
      {isSelected && !isEditing && (
        <ResizeHandles nodeId={node.id} width={node.width} height={node.height} zoom={zoom} />
      )}
    </div>
  );
}

