import { useCanvasStore } from '../hooks/useCanvasStore';
import type { StrokeType, LineType, EndpointType, DrawStyle } from '../types';
import { STROKE_COLORS } from '../types';

interface Props {
  edgeId: string;
  position: { x: number; y: number };
  onClose: () => void;
}

export default function EdgeContextMenu({ edgeId, position, onClose }: Props) {
  const { state, dispatch } = useCanvasStore();
  const edge = state.edges.find(e => e.id === edgeId);
  if (!edge) return null;
  const { style } = edge;

  const update = (updates: Partial<typeof style>) => dispatch({ type: 'UPDATE_EDGE_STYLE', id: edgeId, style: updates });

  const BtnGroup = <T extends string>({ options, value, onChange, render }: {
    options: T[]; value: T; onChange: (v: T) => void;
    render: (v: T) => React.ReactNode;
  }) => (
    <div className="flex gap-1">
      {options.map(o => (
        <button key={o}
          className={`w-8 h-7 rounded border flex items-center justify-center text-xs ${value === o ? 'bg-accent border-foreground' : 'border-border'}`}
          onClick={() => onChange(o)}>{render(o)}</button>
      ))}
    </div>
  );

  return (
    <div className="fixed inset-0 z-50" onClick={onClose}>
      <div className="absolute w-80 border border-border rounded-lg bg-card shadow-lg overflow-hidden"
        style={{ left: position.x, top: position.y }}
        onClick={e => e.stopPropagation()}>

        {/* Connect nodes / free form */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <span className="text-sm text-foreground">connect nodes or free form</span>
          <button className={`w-10 h-5 rounded-full relative transition-colors ${edge.freeForm ? 'bg-primary' : 'bg-muted'}`}
            onClick={() => dispatch({ type: 'UPDATE_EDGE', id: edgeId, updates: { freeForm: !edge.freeForm } })}>
            <div className={`w-4 h-4 rounded-full bg-card border border-border absolute top-0.5 transition-all ${edge.freeForm ? 'left-5' : 'left-0.5'}`} />
          </button>
        </div>

        {/* Endpoints */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <span className="text-sm text-foreground">end points</span>
          <div className="flex gap-1">
            <button className={`w-8 h-7 rounded border flex items-center justify-center text-xs ${style.startEndpoint === 'arrow' ? 'bg-accent border-foreground' : 'border-border'}`}
              onClick={() => update({ startEndpoint: style.startEndpoint === 'arrow' ? 'none' as EndpointType : 'arrow' as EndpointType })}>←</button>
            <button className={`w-8 h-7 rounded border flex items-center justify-center text-xs ${style.startEndpoint === 'arrow' && style.endEndpoint === 'arrow' ? 'bg-accent border-foreground' : 'border-border'}`}
              onClick={() => { update({ startEndpoint: 'arrow', endEndpoint: 'arrow' }); }}>↔</button>
            <button className={`w-8 h-7 rounded border flex items-center justify-center text-xs ${style.endEndpoint === 'arrow' && style.startEndpoint === 'none' ? 'bg-accent border-foreground' : 'border-border'}`}
              onClick={() => update({ startEndpoint: 'none' as EndpointType, endEndpoint: 'arrow' as EndpointType })}>→</button>
          </div>
        </div>

        {/* Stroke type */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <span className="text-sm text-foreground">stroke types</span>
          <BtnGroup
            options={['solid', 'dashed', 'dotted', 'wavy'] as StrokeType[]}
            value={style.strokeType}
            onChange={(v: StrokeType) => update({ strokeType: v })}
            render={(v: StrokeType) => v === 'solid' ? '—' : v === 'dashed' ? '- -' : v === 'dotted' ? '···' : '~'}
          />
        </div>

        {/* Rounded + Line type */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <div className="flex items-center gap-2">
            <span className="text-sm text-foreground">rounded</span>
            <button className={`w-9 h-5 rounded-full relative transition-colors ${style.rounded ? 'bg-primary' : 'bg-muted'}`}
              onClick={() => update({ rounded: !style.rounded })}>
              <div className={`w-3.5 h-3.5 rounded-full bg-card border border-border absolute top-[3px] transition-all ${style.rounded ? 'left-[18px]' : 'left-[3px]'}`} />
            </button>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-foreground">line</span>
            <BtnGroup
              options={['straight', 'step', 'curved'] as LineType[]}
              value={style.lineType}
              onChange={(v: LineType) => update({ lineType: v })}
              render={(v: LineType) => v === 'straight' ? '/' : v === 'step' ? '⌐' : '∿'}
            />
          </div>
        </div>

        {/* Stroke color */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <span className="text-sm text-foreground">stroke color</span>
          <div className="flex gap-1.5">
            {STROKE_COLORS.map(c => (
              <div key={c} className={`w-5 h-5 rounded-full cursor-pointer border-2 ${style.strokeColor === c ? 'border-foreground' : 'border-transparent'}`}
                style={{ background: c }} onClick={() => update({ strokeColor: c })} />
            ))}
          </div>
        </div>

        {/* Weight */}
        <div className="px-4 py-2.5 flex items-center gap-3 border-b border-border">
          <span className="text-sm text-foreground shrink-0">weight</span>
          <input type="range" min={1} max={8} value={style.strokeWidth} className="flex-1"
            onChange={e => update({ strokeWidth: Number(e.target.value) })} />
          <span className="text-xs text-muted-foreground w-6">{style.strokeWidth}px</span>
        </div>

        {/* Drawing style */}
        <div className="px-4 py-2.5 flex items-center justify-between border-b border-border">
          <span className="text-sm text-foreground">styling</span>
          <div className="flex gap-1">
            {(['pencil', 'mechanical'] as DrawStyle[]).map(ds => (
              <button key={ds} className={`px-2.5 py-1 rounded text-xs border ${style.drawStyle === ds ? 'bg-accent border-foreground' : 'border-border'}`}
                onClick={() => update({ drawStyle: ds })}>{ds}</button>
            ))}
          </div>
        </div>

        {/* Mid-line label */}
        <div className="px-4 py-2.5 flex items-center justify-between">
          <span className="text-sm text-foreground">mid line text label</span>
          <button className={`w-9 h-5 rounded-full relative transition-colors ${style.showMidLabel ? 'bg-primary' : 'bg-muted'}`}
            onClick={() => update({ showMidLabel: !style.showMidLabel })}>
            <div className={`w-3.5 h-3.5 rounded-full bg-card border border-border absolute top-[3px] transition-all ${style.showMidLabel ? 'left-[18px]' : 'left-[3px]'}`} />
          </button>
        </div>
        {style.showMidLabel && (
          <div className="px-4 pb-2.5">
            <input type="text" className="w-full px-2 py-1 border border-border rounded text-sm bg-background"
              placeholder="Label text..."
              value={style.midLabel}
              onChange={e => update({ midLabel: e.target.value })}
              onMouseDown={e => e.stopPropagation()} />
          </div>
        )}

        {/* Delete */}
        <div className="border-t border-border">
          <div className="px-4 py-2 cursor-pointer hover:bg-destructive/10 text-sm text-destructive"
            onClick={() => { dispatch({ type: 'DELETE_EDGE', id: edgeId }); onClose(); }}>
            delete connection
          </div>
        </div>
      </div>
    </div>
  );
}

files.apps/flobo/src/components/EdgeRenderer.t:
import { useState, useRef, useEffect } from 'react';
import type { CanvasEdge, CanvasNode, AnchorSide } from '../types';

interface Props {
  edge: CanvasEdge;
  fromNode: CanvasNode;
  toNode: CanvasNode;
  isSelected: boolean;
  isEditingLabel: boolean;
  onSelect: (id: string) => void;
  onContextMenu: (e: React.MouseEvent, id: string) => void;
  onDoubleClick: (id: string) => void;
  onLabelChange: (id: string, label: string) => void;
  onLabelBlur: () => void;
}

function getStrokeDasharray(type: string): string | undefined {
  switch (type) {
    case 'dashed': return '8 4';
    case 'dotted': return '2 4';
    case 'wavy': return '4 2 8 2';
    default: return undefined;
  }
}

function getArrowMarker(id: string, color: string) {
  return (
    <marker id={id} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
      <path d="M 0 0 L 10 5 L 0 10 z" fill={color} />
    </marker>
  );
}

/* -------- Elbow path computation -------- */

interface Pt { x: number; y: number }

function anchorPoint(node: CanvasNode, side: AnchorSide): Pt {
  const cx = node.x + node.width / 2;
  const cy = node.y + node.height / 2;
  switch (side) {
    case 'top': return { x: cx, y: node.y };
    case 'bottom': return { x: cx, y: node.y + node.height };
    case 'left': return { x: node.x, y: cy };
    case 'right': return { x: node.x + node.width, y: cy };
  }
}

function anchorDir(side: AnchorSide): 'v' | 'h' {
  return side === 'top' || side === 'bottom' ? 'v' : 'h';
}

function getExitEntry(fromNode: CanvasNode, toNode: CanvasNode, fromAnchor?: AnchorSide, toAnchor?: AnchorSide): { exit: Pt; entry: Pt; exitDir: 'v' | 'h'; entryDir: 'v' | 'h' } {
  // Use stored anchors if available (stable connection points)
  if (fromAnchor && toAnchor) {
    return {
      exit: anchorPoint(fromNode, fromAnchor),
      entry: anchorPoint(toNode, toAnchor),
      exitDir: anchorDir(fromAnchor),
      entryDir: anchorDir(toAnchor),
    };
  }

  // Fallback: compute from relative positions
  const fcx = fromNode.x + fromNode.width / 2;
  const fcy = fromNode.y + fromNode.height / 2;
  const tcx = toNode.x + toNode.width / 2;
  const tcy = toNode.y + toNode.height / 2;
  const dx = tcx - fcx;
  const dy = tcy - fcy;

  let exit: Pt;
  let entry: Pt;
  let exitDir: 'v' | 'h';
  let entryDir: 'v' | 'h';

  if (Math.abs(dy) >= Math.abs(dx)) {
    if (dy >= 0) {
      exit = { x: fcx, y: fromNode.y + fromNode.height };
      entry = { x: tcx, y: toNode.y };
    } else {
      exit = { x: fcx, y: fromNode.y };
      entry = { x: tcx, y: toNode.y + toNode.height };
    }
    exitDir = 'v';
    entryDir = 'v';
  } else {
    if (dx >= 0) {
      exit = { x: fromNode.x + fromNode.width, y: fcy };
      entry = { x: toNode.x, y: tcy };
    } else {
      exit = { x: fromNode.x, y: fcy };
      entry = { x: toNode.x + toNode.width, y: tcy };
    }
    exitDir = 'h';
    entryDir = 'h';
  }

  return { exit, entry, exitDir, entryDir };
}

function buildElbowPoints(exit: Pt, entry: Pt, exitDir: 'v' | 'h'): Pt[] {
  if (exitDir === 'v') {
    const midY = (exit.y + entry.y) / 2;
    return [exit, { x: exit.x, y: midY }, { x: entry.x, y: midY }, entry];
  } else {
    const midX = (exit.x + entry.x) / 2;
    return [exit, { x: midX, y: exit.y }, { x: midX, y: entry.y }, entry];
  }
}

function pointsToRoundedPath(pts: Pt[], radius: number): string {
  if (pts.length < 2) return '';
  const r = Math.max(0, radius);
  const parts: string[] = [`M ${pts[0].x} ${pts[0].y}`];

  for (let i = 1; i < pts.length - 1; i++) {
    const prev = pts[i - 1];
    const curr = pts[i];
    const next = pts[i + 1];

    // Vector from curr to prev
    const dx1 = prev.x - curr.x;
    const dy1 = prev.y - curr.y;
    const len1 = Math.sqrt(dx1 * dx1 + dy1 * dy1);

    // Vector from curr to next
    const dx2 = next.x - curr.x;
    const dy2 = next.y - curr.y;
    const len2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);

    if (len1 === 0 || len2 === 0) {
      parts.push(`L ${curr.x} ${curr.y}`);
      continue;
    }

    const maxR = Math.min(r, len1 / 2, len2 / 2);

    const startX = curr.x + (dx1 / len1) * maxR;
    const startY = curr.y + (dy1 / len1) * maxR;
    const endX = curr.x + (dx2 / len2) * maxR;
    const endY = curr.y + (dy2 / len2) * maxR;

    parts.push(`L ${startX} ${startY}`);
    parts.push(`Q ${curr.x} ${curr.y} ${endX} ${endY}`);
  }

  const last = pts[pts.length - 1];
  parts.push(`L ${last.x} ${last.y}`);
  return parts.join(' ');
}

function computePath(fromNode: CanvasNode, toNode: CanvasNode, lineType: string, rounded: boolean, fromAnchor?: AnchorSide, toAnchor?: AnchorSide): string {
  const { exit, entry, exitDir } = getExitEntry(fromNode, toNode, fromAnchor, toAnchor);

  if (lineType === 'step') {
    const pts = buildElbowPoints(exit, entry, exitDir);
    return rounded ? pointsToRoundedPath(pts, 12) : pts.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
  }

  if (lineType === 'curved') {
    const cx = (exit.x + entry.x) / 2;
    const cy = exit.y - 40;
    return `M ${exit.x} ${exit.y} Q ${cx} ${cy} ${entry.x} ${entry.y}`;
  }

  // straight
  return `M ${exit.x} ${exit.y} L ${entry.x} ${entry.y}`;
}

function getMidpoint(fromNode: CanvasNode, toNode: CanvasNode, lineType: string, fromAnchor?: AnchorSide, toAnchor?: AnchorSide): Pt {
  const { exit, entry, exitDir } = getExitEntry(fromNode, toNode, fromAnchor, toAnchor);
  if (lineType === 'step') {
    const pts = buildElbowPoints(exit, entry, exitDir);
    // Midpoint of the middle segment
    const m1 = pts[1];
    const m2 = pts[2];
    return { x: (m1.x + m2.x) / 2, y: (m1.y + m2.y) / 2 };
  }
  return { x: (exit.x + entry.x) / 2, y: (exit.y + entry.y) / 2 };
}

export default function EdgeRenderer({ edge, fromNode, toNode, isSelected, isEditingLabel, onSelect, onContextMenu, onDoubleClick, onLabelChange, onLabelBlur }: Props) {
  const { style } = edge;
  const inputRef = useRef<HTMLInputElement>(null);
  const [localLabel, setLocalLabel] = useState(style.midLabel);

  useEffect(() => { setLocalLabel(style.midLabel); }, [style.midLabel]);
  useEffect(() => { if (isEditingLabel && inputRef.current) { inputRef.current.focus(); inputRef.current.select(); } }, [isEditingLabel]);

  const markerId = `arrow-${edge.id}`;
  const markerStartId = `arrow-start-${edge.id}`;

  const pathD = computePath(fromNode, toNode, style.lineType, style.rounded, edge.fromAnchor, edge.toAnchor);
  const mid = getMidpoint(fromNode, toNode, style.lineType, edge.fromAnchor, edge.toAnchor);

  const handleLabelKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === 'Escape') {
      e.preventDefault();
      onLabelChange(edge.id, localLabel);
      onLabelBlur();
    }
  };

  return (
    <g>
      <defs>
        {getArrowMarker(markerId, style.strokeColor)}
        {getArrowMarker(markerStartId, style.strokeColor)}
      </defs>
      {/* Invisible hit area */}
      <path
        d={pathD}
        fill="none" stroke="transparent" strokeWidth={16}
        style={{ cursor: 'pointer' }}
        onClick={(e) => { e.stopPropagation(); onSelect(edge.id); }}
        onDoubleClick={(e) => { e.stopPropagation(); onDoubleClick(edge.id); }}
        onContextMenu={(e) => { e.preventDefault(); e.stopPropagation(); onContextMenu(e, edge.id); }}
      />
      {/* Visible line */}
      <path
        d={pathD}
        fill="none"
        stroke={isSelected ? '#6366f1' : style.strokeColor}
        strokeWidth={style.strokeWidth}
        strokeDasharray={getStrokeDasharray(style.strokeType)}
        strokeLinecap={style.rounded ? 'round' : 'butt'}
        strokeLinejoin={style.rounded ? 'round' : 'miter'}
        markerEnd={style.endEndpoint === 'arrow' ? `url(#${markerId})` : undefined}
        markerStart={style.startEndpoint === 'arrow' ? `url(#${markerStartId})` : undefined}
        style={{ filter: style.drawStyle === 'pencil' ? 'url(#pencil-filter)' : undefined }}
      />
      {/* Mid-line label */}
      {(style.showMidLabel || isEditingLabel) && (
        <g>
          <rect
            x={mid.x - 40} y={mid.y - 12} width={80} height={24} rx={6}
            fill="white" stroke={isEditingLabel ? '#6366f1' : '#ddd'} strokeWidth={1}
            style={{ cursor: 'pointer' }}
            onClick={(e) => { e.stopPropagation(); onSelect(edge.id); }}
            onDoubleClick={(e) => { e.stopPropagation(); onDoubleClick(edge.id); }}
          />
          {isEditingLabel ? (
            <foreignObject x={mid.x - 38} y={mid.y - 10} width={76} height={20}>
              <input
                ref={inputRef}
                type="text"
                value={localLabel}
                onChange={e => setLocalLabel(e.target.value)}
                onBlur={() => { onLabelChange(edge.id, localLabel); onLabelBlur(); }}
                onKeyDown={handleLabelKeyDown}
                onMouseDown={e => e.stopPropagation()}
                style={{ width: '100%', height: '100%', fontSize: 11, textAlign: 'center', border: 'none', outline: 'none', background: 'transparent', color: '#333', fontFamily: 'inherit' }}
              />
            </foreignObject>
          ) : (
            <text x={mid.x} y={mid.y + 4} textAnchor="middle" fontSize={11} fill="#333">
              {style.midLabel || ''}
            </text>
          )}
        </g>
      )}
    </g>
  );
}

