import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Zap, GitBranch, MousePointer2, Palette, Layers, Share2, PenTool, Move, BarChart3, LineChart, Workflow, Circle, ChevronRight, FlaskConical, Dna } from 'lucide-react';
import PageLayout, { hand, serif } from './PageLayout';

const FEATURES = [
  { icon: Zap, title: 'quickflow creation', desc: 'click any directional handle on a selected node to instantly branch a new connected node in that direction. the fastest way to build flowcharts ever made.' },
  { icon: GitBranch, title: 'smart elbowed connectors', desc: 'edges route automatically between nodes with orthogonal paths and rounded corners. no manual routing needed — they just look right.' },
  { icon: MousePointer2, title: 'drag to connect', desc: 'drag from any quickflow handle onto an existing node to create a connection. a live preview line follows your cursor as you drag.' },
  { icon: Palette, title: 'deep node customization', desc: 'every node supports fill color, border color, border width, border radius, border style, per-side borders, opacity, font size, font weight, text alignment, and more.' },
  { icon: Layers, title: 'infinite canvas', desc: 'pan, zoom, and work on an unlimited whiteboard with a clean dotted grid background. scroll to zoom, drag to pan.' },
  { icon: Share2, title: 'auto-layout', desc: 'auto-arrange your nodes in hierarchical tree layouts. choose top-down or sideways orientation. great for cleaning up messy diagrams.' },
  { icon: PenTool, title: 'freehand annotation', desc: 'switch to annotate mode and draw directly on the canvas with customizable colors and line widths. mark up your diagrams naturally.' },
  { icon: Move, title: 'resize & reorder', desc: 'drag resize handles on any selected node. bring forward, send backward. full z-index control for layered compositions.' },
];

const VISUAL_TYPES = [
  {
    title: 'chart',
    icon: BarChart3,
    color: 'hsl(var(--chart-1))',
    definition: 'a generic term for any visual representation of data, no matter the form or shape it takes.',
    examples: 'pie charts, bar charts, donut charts, area charts, radar charts',
    flobo: 'use flobo nodes as chart segments with custom colors, labels, and proportional sizing to build any chart type.',
  },
  {
    title: 'graph',
    icon: LineChart,
    color: 'hsl(var(--chart-4))',
    definition: 'a visual representation of data plotted on two or more axes. a graph is a specific type of plot.',
    examples: 'line graphs, scatter plots, bar graphs, histograms',
    flobo: 'lay out axis labels as nodes, plot data points as small circles, and connect them with styled edges.',
  },
  {
    title: 'diagram',
    icon: Workflow,
    color: 'hsl(var(--chart-2))',
    definition: 'any visual way of representing and visualizing information — not necessarily numerical data.',
    examples: 'flowcharts, venn diagrams, org charts, mind maps, network diagrams, er diagrams',
    flobo: 'this is flobo\'s home turf. quickflow handles, elbowed connectors, and deep styling make every diagram beautiful.',
  },
  {
    title: 'plot',
    icon: Circle,
    color: 'hsl(var(--chart-5))',
    definition: 'any representation that tracks a variable in terms of some other variable. a graph is a type of plot.',
    examples: 'scatter plots, box plots, contour plots, density plots',
    flobo: 'position nodes precisely on the canvas grid to represent data points, with labels and annotations for context.',
  },
];

function CollapsibleSection({ icon: Icon, title, defaultOpen, children }: { icon: React.ElementType; title: string; defaultOpen: boolean; children: React.ReactNode }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="border border-border/60 rounded-xl overflow-hidden">
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center gap-3 px-5 py-4 text-left hover:bg-accent/30 transition-colors"
      >
        <Icon size={16} className="text-primary shrink-0" />
        <span className="text-sm" style={{ fontFamily: hand }}>{title}</span>
        <ChevronRight size={14} className={`ml-auto text-muted-foreground transition-transform duration-200 ${open ? 'rotate-90' : ''}`} />
      </button>
      {open && <div className="px-5 pb-5 pt-1">{children}</div>}
    </div>
  );
}

export default function FeaturesPage() {
  return (
    <PageLayout>
      <div className="max-w-4xl mx-auto px-6 py-20 md:py-28">
        <p className="text-xs text-primary mb-3 tracking-wider uppercase" style={{ fontFamily: hand }}>features</p>
        <h1 className="text-3xl md:text-5xl mb-4 tracking-tight" style={{ fontFamily: serif }}>
          everything flobo can do
        </h1>
        <p className="text-muted-foreground mb-16 max-w-lg">pixel-level control over every node, edge, and connection.</p>
        <div className="grid md:grid-cols-2 gap-6">
          {FEATURES.map(f => {
            const Icon = f.icon;
            return (
              <div key={f.title} className="bg-card border border-border rounded-xl p-6">
                <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center mb-3">
                  <Icon size={18} className="text-primary" />
                </div>
                <h3 className="mb-2 text-sm" style={{ fontFamily: serif, fontSize: 17 }}>{f.title}</h3>
                <p className="text-xs text-muted-foreground leading-relaxed">{f.desc}</p>
              </div>
            );
          })}
        </div>
      </div>

      {/* chart vs graph vs diagram vs plot */}
      <div className="border-t border-border/40 bg-card/40">
        <div className="max-w-6xl mx-auto px-6 py-20 md:py-28">
          <p className="text-xs text-primary mb-3 tracking-wider uppercase" style={{ fontFamily: hand }}>know the difference</p>
          <h2 className="text-3xl md:text-4xl mb-4 tracking-tight" style={{ fontFamily: serif }}>
            figures in datawizardry
          </h2>
          <p className="text-muted-foreground mb-14 max-w-xl">
            people use these words interchangeably — but they each mean something specific. and yes, flobo lets you make all of them.
          </p>

          <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-5" style={{ gridTemplateRows: 'repeat(6, auto)' }}>
            {VISUAL_TYPES.map(v => {
              const Icon = v.icon;
              return (
                <div key={v.title} className="bg-background border border-border rounded-xl p-5 grid" style={{ gridTemplateRows: 'subgrid', gridRow: 'span 6' }}>
                  {/* row 1: icon */}
                  <div
                    className="w-10 h-10 rounded-lg flex items-center justify-center mb-4"
                    style={{ backgroundColor: `${v.color}15` }}
                  >
                    <Icon size={20} style={{ color: v.color }} />
                  </div>
                  {/* row 2: title */}
                  <h3 className="text-lg mb-3" style={{ fontFamily: hand }}>{v.title}</h3>

                  {/* row 3: definition */}
                  <div className="mb-3">
                    <p className="text-[10px] uppercase tracking-wider text-muted-foreground/60 mb-1">definition</p>
                    <p className="text-xs text-foreground/80 leading-relaxed">{v.definition}</p>
                  </div>

                  {/* row 4: examples — aligned across all columns */}
                  <div className="mb-3">
                    <p className="text-[10px] uppercase tracking-wider text-muted-foreground/60 mb-1">examples</p>
                    <p className="text-xs text-muted-foreground leading-relaxed">{v.examples}</p>
                  </div>

                  {/* row 5: in flobo label */}
                  <div />

                  {/* row 6: in flobo */}
                  <div className="pt-3 border-t border-border/50">
                    <p className="text-[10px] uppercase tracking-wider mb-1" style={{ color: v.color }}>in flobo</p>
                    <p className="text-xs text-muted-foreground leading-relaxed">{v.flobo}</p>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="mt-10 bg-accent/50 border border-border/50 rounded-xl p-5 md:p-6 text-center">
            <p className="text-sm text-foreground/80 leading-relaxed max-w-2xl mx-auto">
              <span style={{ fontFamily: hand }} className="text-primary text-base">tl;dr</span>
              {' — '}
              a <strong>chart</strong> is the umbrella term. a <strong>graph</strong> is a chart on axes. a <strong>plot</strong> tracks one variable against another (graphs are plots). a <strong>diagram</strong> visualizes information that isn't necessarily numeric — flowcharts, venn diagrams, architecture maps. flobo handles them all on one infinite canvas.
            </p>
          </div>

          {/* collapsible recipe & dna */}
          <div className="mt-14 space-y-3">
            <CollapsibleSection icon={FlaskConical} title="recipe" defaultOpen={false}>
              <p className="text-sm text-foreground/80 leading-relaxed mb-4">
                the datawizardry portion of flobo aims to be a bridge of sorts —
              </p>
              <div className="flex flex-wrap gap-2 mb-5">
                {['canva quickflow', 'flourish.studio', 'figma / figjam', 'd3.js / chart.js / plotly', 'rawgraphs.io', 'infogram', 'deepnotes.app', 'observablehq notebooks'].map(t => (
                  <span key={t} className="bg-primary/10 text-primary text-[11px] px-2.5 py-1 rounded-full">{t}</span>
                ))}
              </div>
              <p className="text-sm text-foreground/80 leading-relaxed mb-3">
                somewhat like a <em>brainstorming-person's tableau</em> — focused on <strong>interactive</strong>, <strong>nested</strong> data visualization and <strong>visual reactive storytelling</strong>.
              </p>
              <p className="text-sm text-muted-foreground leading-relaxed">
                but without the bottlenecks those tools have: cloud lock-in, freemium-only watermarked or static exports, forced accounts. flobo will allow <strong>no-login creation</strong> (localstorage), <strong>actual interactive exports</strong> in json, html/css/js, or vector — to be used, edited, and hosted wherever you want.
              </p>
              <p className="text-sm text-foreground/70 leading-relaxed mt-4 italic">
                because your data is yours.
              </p>
              <Link to="/datawizardry" className="inline-flex items-center gap-1.5 text-xs text-primary mt-5 hover:underline">
                read more about datawizardry <ChevronRight size={12} />
              </Link>
            </CollapsibleSection>

            <CollapsibleSection icon={Dna} title="dna" defaultOpen={false}>
              <p className="text-sm text-foreground/80 leading-relaxed mb-3">
                datawizardry isn't a bolt-on feature — it's woven into flobo's dna. every node, edge, and canvas primitive is designed to double as a data-bindable visualization element.
              </p>
              <p className="text-sm text-muted-foreground leading-relaxed mb-3">
                the same shapes you use for flowcharts become chart segments. the same edges that connect org-chart boxes become axes or trend lines. your diagram <em>is</em> your dashboard — there's no mode switch, no separate charting tool.
              </p>
              <p className="text-sm text-muted-foreground leading-relaxed">
                this means nesting visualizations inside visualizations, linking live data to node properties, and building reactive canvases that respond to interaction — all within the same infinite canvas you already know.
              </p>
            </CollapsibleSection>
          </div>
        </div>
      </div>
    </PageLayout>
  );
}

