import { useState, useRef, useEffect } from 'react';
import { MousePointer2, Hand, Layers, ChevronRight, GripVertical } from 'lucide-react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import type { CanvasTool } from '../types';

const TOOLS: { icon: typeof MousePointer2; value: CanvasTool; label: string }[] = [
  { icon: MousePointer2, value: 'select', label: 'select' },
  { icon: Hand, value: 'pan', label: 'pan' },
  { icon: Layers, value: 'layers', label: 'layers' },
];

export default function FloatingToolbox() {
  const { state, dispatch } = useCanvasStore();
  const [pos, setPos] = useState({ x: 100, y: 100 });
  const [dragging, setDragging] = useState(false);
  const dragStart = useRef({ mx: 0, my: 0, px: 0, py: 0 });
  const [showLayers, setShowLayers] = useState(false);
  const [collapsed, setCollapsed] = useState(false);

  const handleGripDown = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragging(true);
    dragStart.current = { mx: e.clientX, my: e.clientY, px: pos.x, py: pos.y };
  };

  useEffect(() => {
    if (!dragging) return;
    const onMove = (e: MouseEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setPos({
        x: dragStart.current.px + (e.clientX - dragStart.current.mx),
        y: dragStart.current.py + (e.clientY - dragStart.current.my),
      });
    };
    const onUp = (e: MouseEvent) => {
      e.stopPropagation();
      setDragging(false);
    };
    window.addEventListener('mousemove', onMove, true);
    window.addEventListener('mouseup', onUp, true);
    return () => { window.removeEventListener('mousemove', onMove, true); window.removeEventListener('mouseup', onUp, true); };
  }, [dragging]);

  const handleToolClick = (tool: CanvasTool) => {
    if (tool === 'layers') {
      setShowLayers(!showLayers);
      return;
    }
    dispatch({ type: 'SET_TOOL', tool });
    setShowLayers(false);
  };

  const sortedNodes = [...state.nodes].sort((a, b) => b.zIndex - a.zIndex);

  return (
    <div
      className="absolute z-40"
      style={{ left: pos.x, top: pos.y }}
      onMouseDown={e => e.stopPropagation()}
    >
      {/* Toolbox bar */}
      <div className="flex items-center bg-card border border-border rounded-lg shadow-sm overflow-hidden">
        {/* Drag grip */}
        <div
          className="px-2 py-2 cursor-grab active:cursor-grabbing border-r border-border hover:bg-accent/50 flex items-center"
          onMouseDown={handleGripDown}
        >
          <GripVertical size={14} className="text-muted-foreground/60" />
        </div>

        {/* Tool buttons — hidden when collapsed */}
        {!collapsed && TOOLS.map(t => {
          const Icon = t.icon;
          const isActive = t.value === 'layers' ? showLayers : state.tool === t.value;
          return (
            <button
              key={t.value}
              className={`px-2.5 py-2 transition-colors ${isActive ? 'bg-accent text-foreground' : 'text-muted-foreground hover:bg-accent/50 hover:text-foreground'}`}
              onClick={() => handleToolClick(t.value)}
              title={t.label}
            >
              <Icon size={16} strokeWidth={1.5} />
            </button>
          );
        })}

        {/* Collapse toggle — right chevron, to the right of layers */}
        <button
          className="px-1.5 py-2 border-l border-border text-muted-foreground hover:bg-accent/50 hover:text-foreground transition-colors"
          onClick={() => { setCollapsed(!collapsed); setShowLayers(false); }}
          title={collapsed ? 'expand' : 'collapse'}
        >
          <ChevronRight size={13} className={`transition-transform ${collapsed ? '' : 'rotate-180'}`} />
        </button>
      </div>

      {/* Layers panel */}
      {showLayers && !collapsed && (
        <div className="mt-1 w-56 bg-card border border-border rounded-lg shadow-lg overflow-hidden">
          <div className="px-3 py-1.5 text-[10px] uppercase tracking-wider text-muted-foreground border-b border-border">
            layers ({state.nodes.length})
          </div>
          <div className="max-h-48 overflow-y-auto">
            {sortedNodes.length === 0 && (
              <div className="px-3 py-2 text-xs text-muted-foreground">no nodes yet</div>
            )}
            {sortedNodes.map(n => (
              <div
                key={n.id}
                className={`px-3 py-1.5 text-xs flex items-center justify-between cursor-pointer hover:bg-accent ${state.selectedNodeIds.includes(n.id) ? 'bg-accent' : ''}`}
                onClick={() => dispatch({ type: 'SELECT_NODE', id: n.id })}
              >
                <span className="truncate flex-1 text-foreground">{n.label || n.shape}</span>
                <div className="flex items-center gap-1 ml-2 shrink-0">
                  <span className="text-[9px] text-muted-foreground">z:{n.zIndex}</span>
                  <button className="p-0.5 rounded hover:bg-muted" title="bring forward"
                    onClick={e => { e.stopPropagation(); dispatch({ type: 'BRING_FORWARD', id: n.id }); }}>
                    <span className="text-[9px]">↑</span>
                  </button>
                  <button className="p-0.5 rounded hover:bg-muted" title="send backward"
                    onClick={e => { e.stopPropagation(); dispatch({ type: 'SEND_BACKWARD', id: n.id }); }}>
                    <span className="text-[9px]">↓</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

