import { useState } from 'react';
import { Check, Link, ChevronRight, ChevronDown, ChevronUp, ArrowUpToLine, ArrowDownToLine, Plus } from 'lucide-react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import type { ShapeType, NodeColor, BorderStyleType } from '../types';
import { PASTEL_COLORS } from '../types';

interface Props {
  nodeId: string;
  position: { x: number; y: number };
  onClose: () => void;
}

const SHAPE_OPTIONS: { label: string; value: ShapeType }[] = [
  { label: 'rectangle', value: 'rectangle' },
  { label: 'circle', value: 'circle' },
  { label: 'diamond', value: 'diamond' },
  { label: 'polygon', value: 'polygon' },
  { label: 'oval', value: 'oval' },
  { label: 'trapezoid', value: 'trapezoid' },
  { label: 'parallelogram', value: 'parallelogram' },
  { label: 'text only', value: 'text' },
];

const BORDER_STYLE_LABELS: Record<BorderStyleType, string> = {
  solid: 'solid',
  dashed: 'dashed',
  dotted: 'dotted',
};

function SubMenu({ children, label }: { children: React.ReactNode; label: string }) {
  return (
    <div className="relative group/sub">
      <div className="px-3 py-1.5 flex items-center justify-between cursor-default hover:bg-accent text-xs">
        <span className="text-foreground">{label}</span>
        <ChevronRight size={12} className="text-muted-foreground" />
      </div>
      <div className="absolute left-full top-0 ml-0.5 hidden group-hover/sub:block z-50">
        {children}
      </div>
    </div>
  );
}

function NestedSubMenu({ children, label }: { children: React.ReactNode; label: string }) {
  return (
    <div className="relative group/nested">
      <div className="px-3 py-1.5 flex items-center justify-between cursor-default hover:bg-accent text-xs">
        <span className="text-foreground">{label}</span>
        <ChevronRight size={10} className="text-muted-foreground" />
      </div>
      <div className="absolute left-full top-0 ml-0.5 hidden group-hover/nested:block z-50">
        {children}
      </div>
    </div>
  );
}

/* ---- Adjust Color panel ---- */
function AdjustColorPanel({ nodeId }: { nodeId: string }) {
  const { state, dispatch } = useCanvasStore();
  const node = state.nodes.find(n => n.id === nodeId);
  const [showPicker, setShowPicker] = useState(false);
  const [customHex, setCustomHex] = useState(node?.style.fillColor ?? '#F0F0F0');
  if (!node) return null;

  const applyColor = (c: string) => {
    dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { fillColor: c as NodeColor } });
  };

  return (
    <div className="w-[172px] border border-border rounded-md bg-card shadow-lg p-2.5 space-y-2.5">
      {/* Color grid: 5 per row, 9 colors + custom picker = 10 circles */}
      <div className="grid grid-cols-5 gap-1.5 justify-items-center">
        {PASTEL_COLORS.map(c => (
          <div
            key={c}
            className={`w-7 h-7 rounded-full cursor-pointer border-2 transition-transform hover:scale-110 ${node.style.fillColor === c ? 'border-foreground' : 'border-transparent'}`}
            style={{ background: c }}
            onClick={() => applyColor(c)}
          />
        ))}
        {/* Custom hex circle */}
        <div
          className={`w-7 h-7 rounded-full cursor-pointer border-2 flex items-center justify-center transition-transform hover:scale-110 ${showPicker ? 'border-foreground' : 'border-border'}`}
          style={{ background: '#ffffff' }}
          onClick={() => setShowPicker(!showPicker)}
        >
          <Plus size={12} className="text-muted-foreground" />
        </div>
      </div>

      {/* Custom hex picker */}
      {showPicker && (
        <div className="flex items-center gap-1.5">
          <input
            type="color"
            value={customHex}
            className="w-7 h-7 rounded cursor-pointer border-0 p-0 shrink-0"
            onChange={e => { setCustomHex(e.target.value); applyColor(e.target.value); }}
            onMouseDown={e => e.stopPropagation()}
          />
          <input
            type="text"
            value={customHex}
            className="flex-1 px-1.5 py-0.5 border border-border rounded text-[10px] bg-background font-mono uppercase"
            maxLength={7}
            onChange={e => {
              const v = e.target.value;
              setCustomHex(v);
              if (/^#[0-9A-Fa-f]{6}$/.test(v)) applyColor(v);
            }}
            onMouseDown={e => e.stopPropagation()}
          />
        </div>
      )}

      {/* Opacity slider */}
      <div>
        <label className="text-[10px] text-muted-foreground">opacity: {Math.round(node.style.opacity * 100)}%</label>
        <input
          type="range" min={10} max={100}
          value={Math.round(node.style.opacity * 100)}
          className="w-full mt-0.5 h-1"
          onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { opacity: Number(e.target.value) / 100 } })}
        />
      </div>
    </div>
  );
}

/* ---- Style Node panel ---- */
function StyleNodePanel({ nodeId }: { nodeId: string }) {
  const { state, dispatch } = useCanvasStore();
  const node = state.nodes.find(n => n.id === nodeId);
  if (!node) return null;

  const sides = node.style.borderSides ?? { top: true, right: true, bottom: true, left: true };
  const toggleSide = (side: 'top' | 'right' | 'bottom' | 'left') => {
    dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { borderSides: { ...sides, [side]: !sides[side] } } });
  };

  return (
    <div className="w-56 border border-border rounded-md bg-card shadow-lg overflow-visible py-1">
      {/* Corner rounding */}
      <div className="px-2.5 py-1.5">
        <label className="text-[10px] text-muted-foreground">corner rounding: {node.style.borderRadius}px</label>
        <input type="range" min={0} max={48} value={node.style.borderRadius} className="w-full mt-0.5 h-1"
          onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { borderRadius: Number(e.target.value) } })} />
      </div>

      {/* Padding */}
      <div className="px-2.5 py-1.5">
        <label className="text-[10px] text-muted-foreground">padding: {node.style.padding}px</label>
        <input type="range" min={0} max={32} value={node.style.padding} className="w-full mt-0.5 h-1"
          onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { padding: Number(e.target.value) } })} />
      </div>

      {/* Border — opens sideways */}
      <NestedSubMenu label="border">
        <div className="w-52 border border-border rounded-md bg-card shadow-lg p-2.5 space-y-2">
          {/* Thickness */}
          <div>
            <label className="text-[10px] text-muted-foreground">thickness: {node.style.borderWidth}px</label>
            <input type="range" min={0} max={8} value={node.style.borderWidth} className="w-full mt-0.5 h-1"
              onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { borderWidth: Number(e.target.value) } })} />
          </div>

          {/* Color + Style — same row */}
          <div className="flex items-end gap-2">
            <div className="flex-1">
              <label className="text-[10px] text-muted-foreground block mb-0.5">color</label>
              <input type="color" value={node.style.borderColor} className="w-full h-6 rounded cursor-pointer border border-border"
                onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { borderColor: e.target.value } })} />
            </div>
            <div className="flex-1">
              <label className="text-[10px] text-muted-foreground block mb-0.5">style</label>
              <select
                className="w-full h-6 px-1 text-[10px] border border-border rounded bg-background text-foreground cursor-pointer"
                value={node.style.borderStyle}
                onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { borderStyle: e.target.value as BorderStyleType } })}
              >
                {Object.entries(BORDER_STYLE_LABELS).map(([val, label]) => (
                  <option key={val} value={val}>{label}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Border sides */}
          <div>
            <label className="text-[10px] text-muted-foreground mb-1 block">sides</label>
            <div className="flex gap-1.5">
              {(['top', 'right', 'bottom', 'left'] as const).map(side => (
                <label key={side} className="flex items-center gap-0.5 text-[10px] text-foreground cursor-pointer">
                  <input type="checkbox" checked={sides[side]} onChange={() => toggleSide(side)}
                    className="w-3 h-3 rounded accent-primary" />
                  {side[0].toUpperCase()}
                </label>
              ))}
            </div>
          </div>
        </div>
      </NestedSubMenu>
    </div>
  );
}

/* ---- Main context menu ---- */

const PHOTO_SHAPES = new Set<string>(['polaroid', 'film_strip', 'photo_strip']);
const ORIENTABLE_SHAPES = new Set<string>(['polaroid', 'photo_strip']);

export default function NodeContextMenu({ nodeId, position, onClose }: Props) {
  const { state, dispatch } = useCanvasStore();
  const node = state.nodes.find(n => n.id === nodeId);
  if (!node) return null;
  const isPhotoShape = PHOTO_SHAPES.has(node.shape);

  const makeSibling = () => {
    if (node.parentId) {
      dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { parentId: null } });
    }
    onClose();
  };

  const makeChild = () => {
    if (!node.parentId) {
      const incomingEdge = state.edges.find(e => e.toNodeId === nodeId);
      if (incomingEdge) {
        const parentNode = state.nodes.find(n => n.id === incomingEdge.fromNodeId);
        if (parentNode) {
          dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { parentId: parentNode.id } });
          dispatch({ type: 'UPDATE_NODE', id: parentNode.id, updates: { childIds: [...parentNode.childIds, nodeId] } });
        }
      }
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50" onClick={onClose}>
      <div className="absolute" style={{ left: position.x, top: position.y }} onClick={e => e.stopPropagation()}>
        <div className="w-56 border border-border rounded-md bg-card shadow-lg overflow-visible py-1">

          {/* Quickflow toggle */}
          <div className="px-3 py-1.5 flex items-center justify-between cursor-pointer hover:bg-accent text-xs"
            onClick={() => dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { quickflowEnabled: !node.quickflowEnabled } })}>
            <span className="text-foreground">quickflow mode</span>
            {node.quickflowEnabled && <Check size={12} className="text-primary" />}
          </div>

          <div className="h-px bg-border mx-1 my-0.5" />

          {/* Change shape / orientation */}
          {isPhotoShape ? (
            <>
              {ORIENTABLE_SHAPES.has(node.shape) && (
                <SubMenu label="change orientation">
                  <div className="w-40 border border-border rounded-md bg-card shadow-lg py-1">
                    {(['portrait', 'landscape'] as const).map(o => (
                      <div key={o}
                        className={`px-3 py-1.5 text-xs cursor-pointer hover:bg-accent flex items-center justify-between ${node.orientation === o ? 'text-primary' : 'text-foreground'}`}
                        onClick={() => {
                          if (node.orientation !== o) {
                            // Swap width and height when changing orientation
                            dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { orientation: o, width: node.height, height: node.width } });
                          }
                          onClose();
                        }}>
                        <span>{o}</span>
                        {node.orientation === o && <Check size={11} />}
                      </div>
                    ))}
                  </div>
                </SubMenu>
              )}

              {/* Photo strip count */}
              {node.shape === 'photo_strip' && (
                <div className="px-3 py-1.5 flex items-center justify-between text-xs">
                  <span className="text-foreground">photos</span>
                  <div className="flex items-center gap-1">
                    <button className="w-5 h-5 rounded border border-border flex items-center justify-center text-xs hover:bg-accent"
                      onClick={() => {
                        if (node.photoStripCount > 1) {
                          dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { photoStripCount: node.photoStripCount - 1 } });
                        }
                      }}>−</button>
                    <span className="w-5 text-center text-xs">{node.photoStripCount}</span>
                    <button className="w-5 h-5 rounded border border-border flex items-center justify-center text-xs hover:bg-accent"
                      onClick={() => {
                        if (node.photoStripCount < 8) {
                          dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { photoStripCount: node.photoStripCount + 1 } });
                        }
                      }}>+</button>
                  </div>
                </div>
              )}

              {/* Pushpin toggle */}
              <div className="px-3 py-1.5 flex items-center justify-between cursor-pointer hover:bg-accent text-xs"
                onClick={() => { /* non-functional placeholder */ }}>
                <span className="text-foreground">pushpin</span>
              </div>

              {/* Washi tape toggle */}
              <div className="px-3 py-1.5 flex items-center justify-between cursor-pointer hover:bg-accent text-xs"
                onClick={() => { /* non-functional placeholder */ }}>
                <span className="text-foreground">washi tape</span>
              </div>

              {/* Add text */}
              <div className="px-3 py-1.5 cursor-pointer hover:bg-accent text-xs text-foreground"
                onClick={() => { dispatch({ type: 'SET_EDITING', id: nodeId }); onClose(); }}>
                add text
              </div>
            </>
          ) : (
            <SubMenu label="change shape">
              <div className="w-44 border border-border rounded-md bg-card shadow-lg py-1">
                {SHAPE_OPTIONS.map(s => (
                  <div key={s.value}
                    className={`px-3 py-1.5 text-xs cursor-pointer hover:bg-accent flex items-center justify-between ${node.shape === s.value ? 'text-primary' : 'text-foreground'}`}
                    onClick={() => { dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { shape: s.value } }); onClose(); }}>
                    <span>{s.label}</span>
                    {node.shape === s.value && <Check size={11} />}
                  </div>
                ))}
                {node.shape === 'polygon' && (
                  <div className="px-3 py-1.5 border-t border-border">
                    <label className="text-[10px] text-muted-foreground">edges: {node.polygonEdges}</label>
                    <input type="range" min={3} max={12} value={node.polygonEdges} className="w-full mt-0.5 h-1"
                      onChange={e => dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: { polygonEdges: Number(e.target.value) } })} />
                  </div>
                )}
              </div>
            </SubMenu>
          )}

          {/* Adjust color */}
          <SubMenu label="adjust color">
            <AdjustColorPanel nodeId={nodeId} />
          </SubMenu>

          {/* Style node */}
          <SubMenu label="style node">
            <StyleNodePanel nodeId={nodeId} />
          </SubMenu>

          {/* Style text */}
          <SubMenu label="style text">
            <div className="w-48 border border-border rounded-md bg-card shadow-lg p-2.5 space-y-2">
              <div>
                <label className="text-[10px] text-muted-foreground">font size: {node.style.fontSize}px</label>
                <input type="range" min={10} max={32} value={node.style.fontSize} className="w-full mt-0.5 h-1"
                  onChange={e => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { fontSize: Number(e.target.value) } })} />
              </div>
              <div className="flex gap-1">
                {(['normal', 'bold'] as const).map(w => (
                  <button key={w} className={`px-2 py-0.5 rounded text-[10px] border ${node.style.fontWeight === w ? 'bg-accent border-foreground' : 'border-border'}`}
                    onClick={() => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { fontWeight: w } })}>{w}</button>
                ))}
              </div>
              <div className="flex gap-1">
                {(['left', 'center', 'right'] as const).map(a => (
                  <button key={a} className={`px-2 py-0.5 rounded text-[10px] border ${node.style.textAlign === a ? 'bg-accent border-foreground' : 'border-border'}`}
                    onClick={() => dispatch({ type: 'UPDATE_NODE_STYLE', id: nodeId, style: { textAlign: a } })}>{a}</button>
                ))}
              </div>
            </div>
          </SubMenu>

          {/* Hierarchy setup */}
          <SubMenu label="hierarchy setup">
            <div className="w-44 border border-border rounded-md bg-card shadow-lg py-1 overflow-visible">
              <div className="px-3 py-1 text-[10px] text-muted-foreground border-b border-border">
                current: {node.parentId ? 'child node' : 'root node'}
              </div>
              <NestedSubMenu label="sibling node">
                <div className="w-48 border border-border rounded-md bg-card shadow-lg p-2.5">
                  <p className="text-[10px] text-muted-foreground mb-2">
                    detach this node from its parent to make it a sibling (root-level node).
                  </p>
                  <button
                    className={`px-2.5 py-1 rounded border text-[10px] transition-colors w-full ${!node.parentId ? 'bg-accent border-foreground text-foreground' : 'border-border hover:bg-accent text-foreground'}`}
                    onClick={makeSibling}
                  >
                    {node.parentId ? 'make sibling' : 'already a root node'}
                  </button>
                </div>
              </NestedSubMenu>
              <NestedSubMenu label="child node">
                <div className="w-48 border border-border rounded-md bg-card shadow-lg p-2.5">
                  <p className="text-[10px] text-muted-foreground mb-2">
                    attach this node as a child of its connected parent via incoming edges.
                  </p>
                  <button
                    className={`px-2.5 py-1 rounded border text-[10px] transition-colors w-full ${node.parentId ? 'bg-accent border-foreground text-foreground' : 'border-border hover:bg-accent text-foreground'}`}
                    onClick={makeChild}
                  >
                    {node.parentId ? 'already a child node' : 'make child'}
                  </button>
                </div>
              </NestedSubMenu>
