import { useCallback } from 'react';
import { ArrowUp, ArrowDown, ArrowLeft, ArrowRight } from 'lucide-react';
import type { ConnectingState } from '../types';

interface Props {
  nodeId: string;
  width: number;
  height: number;
  onStartConnect: (state: ConnectingState) => void;
  onQuickCreate: (nodeId: string, dir: 'up' | 'down' | 'left' | 'right') => void;
}

const btnClass = 'w-7 h-7 rounded-full border border-border bg-card flex items-center justify-center cursor-crosshair hover:bg-accent hover:scale-110 transition-all z-20';

type Dir = 'up' | 'down' | 'left' | 'right';

const ARROW_ICONS = {
  up: ArrowUp,
  down: ArrowDown,
  left: ArrowLeft,
  right: ArrowRight,
};

export default function QuickFlowHandles({ nodeId, width, height, onStartConnect, onQuickCreate }: Props) {
  const handleMouseDown = useCallback((dir: Dir, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    onStartConnect({ fromNodeId: nodeId, direction: dir });
  }, [nodeId, onStartConnect]);

  const handleClick = useCallback((dir: Dir, e: React.MouseEvent) => {
    e.stopPropagation();
    onQuickCreate(nodeId, dir);
  }, [nodeId, onQuickCreate]);

  const handles: { dir: Dir; style: React.CSSProperties }[] = [
    { dir: 'up', style: { left: width / 2 - 14, top: -34 } },
    { dir: 'down', style: { left: width / 2 - 14, top: height + 6 } },
    { dir: 'left', style: { left: -34, top: height / 2 - 14 } },
    { dir: 'right', style: { left: width + 6, top: height / 2 - 14 } },
  ];

  return (
    <>
      {handles.map(h => {
        const Icon = ARROW_ICONS[h.dir];
        return (
          <div
            key={h.dir}
            className={btnClass}
            style={{ position: 'absolute', ...h.style }}
            onMouseDown={e => handleMouseDown(h.dir, e)}
            onClick={e => handleClick(h.dir, e)}
          >
            <Icon size={14} strokeWidth={2} className="text-muted-foreground" />
          </div>
        );
      })}
    </>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useCanvasStore } from '../hooks/useCanvasStore';

interface Props {
  nodeId: string;
  width: number;
  height: number;
  zoom: number;
}

type Corner = 'nw' | 'ne' | 'sw' | 'se';

const cursors: Record<Corner, string> = { nw: 'nwse-resize', ne: 'nesw-resize', sw: 'nesw-resize', se: 'nwse-resize' };

export default function ResizeHandles({ nodeId, width, height, zoom }: Props) {
  const { state, dispatch } = useCanvasStore();
  const [resizing, setResizing] = useState<Corner | null>(null);
  const startRef = useRef({ mx: 0, my: 0, w: 0, h: 0, x: 0, y: 0 });

  const startResize = (corner: Corner, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const node = state.nodes.find(n => n.id === nodeId);
    if (!node) return;
    startRef.current = { mx: e.clientX, my: e.clientY, w: node.width, h: node.height, x: node.x, y: node.y };
    setResizing(corner);
  };

  useEffect(() => {
    if (!resizing) return;
    const onMove = (e: MouseEvent) => {
      const dx = (e.clientX - startRef.current.mx) / zoom;
      const dy = (e.clientY - startRef.current.my) / zoom;
      const s = startRef.current;
      const updates: Record<string, number> = {};
      const minSize = 40;

      if (resizing === 'se') {
        updates.width = Math.max(minSize, s.w + dx);
        updates.height = Math.max(minSize, s.h + dy);
      } else if (resizing === 'sw') {
        const newW = Math.max(minSize, s.w - dx);
        updates.width = newW;
        updates.x = s.x + s.w - newW;
        updates.height = Math.max(minSize, s.h + dy);
      } else if (resizing === 'ne') {
        updates.width = Math.max(minSize, s.w + dx);
        const newH = Math.max(minSize, s.h - dy);
        updates.height = newH;
        updates.y = s.y + s.h - newH;
      } else if (resizing === 'nw') {
        const newW = Math.max(minSize, s.w - dx);
        const newH = Math.max(minSize, s.h - dy);
        updates.width = newW;
        updates.height = newH;
        updates.x = s.x + s.w - newW;
        updates.y = s.y + s.h - newH;
      }
      dispatch({ type: 'UPDATE_NODE', id: nodeId, updates });
    };
    const onUp = () => setResizing(null);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
  }, [resizing, nodeId, zoom, dispatch]);

  const positions: Record<Corner, { left: number; top: number }> = {
    nw: { left: -5, top: -5 },
    ne: { left: width - 5, top: -5 },
    sw: { left: -5, top: height - 5 },
    se: { left: width - 5, top: height - 5 },
  };

  return (
    <>
      {(Object.keys(positions) as Corner[]).map(corner => (
        <div
          key={corner}
          className="absolute w-2.5 h-2.5 rounded-full bg-card border-2 z-20"
          style={{ ...positions[corner], cursor: cursors[corner], borderColor: '#6366f1' }}
          onMouseDown={e => startResize(corner, e)}
        />
      ))}
    </>
  );
}

