import type { ShapeType, NodeStyle } from '../types';

interface Props {
  shape: ShapeType;
  width: number;
  height: number;
  style: NodeStyle;
  polygonEdges: number;
  imageUrl?: string;
  imageUrls?: string[];
  orientation?: 'portrait' | 'landscape';
  photoStripCount?: number;
  onImageAreaClick?: (slotIndex?: number) => void;
}

function getPolygonClipPath(edges: number): string {
  const pts: string[] = [];
  for (let i = 0; i < edges; i++) {
    const angle = (Math.PI * 2 * i) / edges - Math.PI / 2;
    const x = 50 + 50 * Math.cos(angle);
    const y = 50 + 50 * Math.sin(angle);
    pts.push(`${x}% ${y}%`);
  }
  return `polygon(${pts.join(', ')})`;
}

const CLIP_PATHS: Record<string, string> = {
  diamond: 'polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)',
  trapezoid: 'polygon(20% 100%, 0% 0%, 100% 0%, 80% 100%)',
  parallelogram: 'polygon(15% 100%, 0% 0%, 85% 0%, 100% 100%)',
  rhombus: 'polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)',
  trapezium: 'polygon(25% 0%, 75% 0%, 100% 100%, 0% 100%)',
};

const SPECIAL_SHAPES = new Set(['polaroid', 'film_strip', 'photo_strip', 'receipt', 'sticky_note', 'image_embed', 'table_grid']);

const PlusIcon = ({ size = 24 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="#999" strokeWidth="1.5">
    <line x1="12" y1="5" x2="12" y2="19" />
    <line x1="5" y1="12" x2="19" y2="12" />
  </svg>
);

export default function ShapeRenderer({ shape, width, height, style, polygonEdges, imageUrl, imageUrls, orientation, photoStripCount, onImageAreaClick }: Props) {
  if (shape === 'text') return null;

  if (SPECIAL_SHAPES.has(shape)) {
    return <SpecialShape shape={shape} width={width} height={height} style={style} imageUrl={imageUrl} imageUrls={imageUrls} orientation={orientation} photoStripCount={photoStripCount} onImageAreaClick={onImageAreaClick} />;
  }

  const isRound = shape === 'circle' || shape === 'oval' || shape === 'semicircle';
  const hasClip = shape === 'diamond' || shape === 'trapezoid' || shape === 'parallelogram' || shape === 'polygon' || shape === 'triangle' || shape === 'semicircle' || shape === 'rhombus' || shape === 'trapezium';

  let clipPath: string | undefined;
  if (shape === 'polygon') clipPath = getPolygonClipPath(polygonEdges);
  else if (shape === 'triangle') clipPath = 'polygon(50% 0%, 100% 100%, 0% 100%)';
  else if (shape === 'semicircle') clipPath = 'ellipse(50% 100% at 50% 100%)';
  else clipPath = CLIP_PATHS[shape];

  const s = style.borderSides ?? { top: true, right: true, bottom: true, left: true };
  const bw = style.borderWidth ?? 1;
  const bc = style.borderColor ?? '#CCCCCC';
  const bs = style.borderStyle ?? 'solid';
  const border = `${bw}px ${bs} ${bc}`;

  return (
    <div
      className="absolute inset-0 pointer-events-none"
      style={{
        width,
        height,
        backgroundColor: style.fillColor,
        borderTop: s.top ? border : 'none',
        borderRight: s.right ? border : 'none',
        borderBottom: s.bottom ? border : 'none',
        borderLeft: s.left ? border : 'none',
        borderRadius: isRound ? '50%' : hasClip ? 0 : style.borderRadius,
        clipPath: hasClip ? clipPath : undefined,
        WebkitClipPath: hasClip ? clipPath : undefined,
        opacity: style.opacity,
      }}
    />
  );
}

function SpecialShape({ shape, width, height, style, imageUrl, imageUrls = [], orientation = 'portrait', photoStripCount = 3, onImageAreaClick }: {
  shape: ShapeType;
  width: number;
  height: number;
  style: NodeStyle;
  imageUrl?: string;
  imageUrls?: string[];
  orientation?: 'portrait' | 'landscape';
  photoStripCount?: number;
  onImageAreaClick?: (slotIndex?: number) => void;
}) {
  const border = `${style.borderWidth ?? 1}px ${style.borderStyle ?? 'solid'} ${style.borderColor ?? '#CCCCCC'}`;

  if (shape === 'polaroid') {
    const isLandscape = orientation === 'landscape';
    const pad = Math.min(width, height) * 0.06;

    if (isLandscape) {
      // Landscape: image takes most of height, text on the right
      const textW = width * 0.22;
      const imgW = width - pad * 2 - textW;
      return (
        <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#fafafa', border, borderRadius: 2, opacity: style.opacity, boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
          <div
            className="absolute pointer-events-auto cursor-pointer"
            style={{ left: pad, top: pad, width: Math.max(imgW, 20), height: height - pad * 2, backgroundColor: '#e0e0e0', overflow: 'hidden' }}
            onClick={(e) => { e.stopPropagation(); onImageAreaClick?.(0); }}
          >
            {imageUrl ? (
              <img src={imageUrl} className="w-full h-full object-cover" alt="" />
            ) : (
              <div className="w-full h-full flex items-center justify-center">
                <PlusIcon />
              </div>
            )}
          </div>
        </div>
      );
    }

    // Portrait (default)
    const imgH = height - pad * 2 - pad * 2.5;
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#fafafa', border, borderRadius: 2, opacity: style.opacity, boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
        <div
          className="absolute pointer-events-auto cursor-pointer"
          style={{ left: pad, top: pad, width: width - pad * 2, height: Math.max(imgH, 20), backgroundColor: '#e0e0e0', overflow: 'hidden' }}
          onClick={(e) => { e.stopPropagation(); onImageAreaClick?.(0); }}
        >
          {imageUrl ? (
            <img src={imageUrl} className="w-full h-full object-cover" alt="" />
          ) : (
            <div className="w-full h-full flex items-center justify-center">
              <PlusIcon />
            </div>
          )}
        </div>
      </div>
    );
  }

  if (shape === 'film_strip') {
    const perf = 6;
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#1a1a1a', border, borderRadius: 2, opacity: style.opacity }}>
        {Array.from({ length: perf }).map((_, i) => (
          <div key={`l${i}`} className="absolute" style={{ left: 4, top: (height / perf) * i + height / perf / 2 - 3, width: 6, height: 6, borderRadius: 1, backgroundColor: '#fafafa' }} />
        ))}
        {Array.from({ length: perf }).map((_, i) => (
          <div key={`r${i}`} className="absolute" style={{ right: 4, top: (height / perf) * i + height / perf / 2 - 3, width: 6, height: 6, borderRadius: 1, backgroundColor: '#fafafa' }} />
        ))}
        <div className="absolute pointer-events-auto cursor-pointer" style={{ left: 16, top: 8, width: width - 32, height: height * 0.4 - 12, backgroundColor: '#e0e0e0', overflow: 'hidden' }}
          onClick={(e) => { e.stopPropagation(); onImageAreaClick?.(0); }}>
          {imageUrl ? <img src={imageUrl} className="w-full h-full object-cover" alt="" /> : (
            <div className="w-full h-full flex items-center justify-center"><PlusIcon size={18} /></div>
          )}
        </div>
        <div className="absolute" style={{ left: 16, top: height * 0.4 + 4, width: width - 32, height: height * 0.4 - 12, backgroundColor: '#3a3a3a', borderRadius: 1 }} />
      </div>
    );
  }

  if (shape === 'photo_strip') {
    const count = photoStripCount || 3;
    // Layout ratios based on the CSS spec
    const sidePad = width * 0.05;
    const topPad = height * 0.025;
    const gap = height * 0.033;
    const textAreaH = height * 0.11;
    const photoW = width - sidePad * 2;
    // photoH = (height - topPad - (count-1)*gap - textAreaH) / count
    const totalPhotoH = height - topPad - (count - 1) * gap - textAreaH;
    const photoH = Math.max(totalPhotoH / count, 10);

    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#fafafa', border, borderRadius: 4, opacity: style.opacity, boxShadow: '0 2px 8px rgba(0,0,0,0.08)' }}>
        {Array.from({ length: count }).map((_, i) => {
          const slotUrl = imageUrls?.[i] || (i === 0 ? imageUrl : undefined);
          const top = topPad + i * (photoH + gap);
          return (
            <div
              key={i}
              className="absolute pointer-events-auto cursor-pointer"
              style={{ left: sidePad, top, width: photoW, height: photoH, backgroundColor: '#e0e0e0', overflow: 'hidden' }}
              onClick={(e) => { e.stopPropagation(); onImageAreaClick?.(i); }}
            >
              {slotUrl ? (
                <img src={slotUrl} className="w-full h-full object-cover" alt="" />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  <PlusIcon size={16} />
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  if (shape === 'sticky_note') {
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: style.fillColor === '#F0F0F0' ? '#FFF9C4' : style.fillColor, opacity: style.opacity, boxShadow: '2px 3px 8px rgba(0,0,0,0.12)' }}>
        <svg className="absolute top-0 right-0" width="20" height="20" viewBox="0 0 20 20">
          <path d="M0,0 L20,0 L0,20 Z" fill="rgba(0,0,0,0.06)" />
        </svg>
      </div>
    );
  }

  if (shape === 'image_embed') {
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, overflow: 'hidden', borderRadius: style.borderRadius ?? 4, opacity: style.opacity }}>
        {imageUrl ? (
          <img src={imageUrl} className="w-full h-full object-contain" alt="" draggable={false} />
        ) : (
          <div
            className="w-full h-full flex flex-col items-center justify-center gap-2 pointer-events-auto cursor-pointer"
            style={{ backgroundColor: '#f0f0f0', border: '2px dashed #ccc', borderRadius: style.borderRadius ?? 4 }}
            onClick={(e) => { e.stopPropagation(); onImageAreaClick?.(0); }}
          >
            <PlusIcon size={28} />
            <span style={{ fontSize: 10, color: '#999', fontFamily: 'monospace' }}>click or paste image</span>
          </div>
        )}
      </div>
    );
  }

  if (shape === 'table_grid') {
    // Table rendering is handled by TableNode in CanvasNode
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#fff', border, borderRadius: style.borderRadius ?? 4, opacity: style.opacity }} />
    );
  }

  if (shape === 'receipt') {
    return (
      <div className="absolute inset-0 pointer-events-none" style={{ width, height, backgroundColor: '#fafafa', opacity: style.opacity }}>
        <svg className="absolute inset-0" width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
          <path d={`M0,0 H${width} V${height - 8} ${Array.from({ length: Math.ceil(width / 12) }).map((_, i) => `L${i * 12 + 6},${height} L${(i + 1) * 12},${height - 8}`).join(' ')} V0 Z`} fill="#fafafa" stroke={style.borderColor || '#ccc'} strokeWidth={style.borderWidth ?? 1} />
        </svg>
        {[0.2, 0.35, 0.5, 0.65].map((r, i) => (
          <div key={i} className="absolute" style={{ left: '15%', top: `${r * 100}%`, width: i < 3 ? '70%' : '40%', height: 1, backgroundColor: '#ddd' }} />
        ))}
      </div>
    );
  }

  return null;
}

