const PHOTO_SHAPES = new Set<ShapeType>(['polaroid', 'film_strip', 'photo_strip']);

function makeTableData(rows: number, cols: number, variant: TableVariant): TableData {
  const hasHeader = variant !== 'default';
  const cells: string[][] = Array.from({ length: rows }, (_, r) =>
    Array.from({ length: cols }, (_, c) => {
      if (hasHeader && r === 0) {
        if (variant === 'kanban') return ['to do', 'in progress', 'review', 'done'][c] ?? `col ${c + 1}`;
        if (variant === 'notion') return ['name', 'status', 'priority', 'date'][c] ?? `col ${c + 1}`;
        if (variant === 'calendar') return ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'][c] ?? '';
        if (variant === 'timetable') return ['time', 'mon', 'tue', 'wed', 'thu', 'fri'][c] ?? '';
        return `col ${c + 1}`;
      }
      if (variant === 'timetable' && c === 0 && r > 0) {
        return `${7 + r}:00`;
      }
      return '';
    })
  );
  return { rows, cols, cells, hasHeader, variant };
}

