  },
];

const MAX_GRID = 8;

function GridPicker({ onSelect }: { onSelect: (rows: number, cols: number) => void }) {
  const [hover, setHover] = useState<{ r: number; c: number } | null>(null);

  return (
    <div className="p-2">
      <div className="grid gap-[3px]" style={{ gridTemplateColumns: `repeat(${MAX_GRID}, 1fr)` }}>
        {Array.from({ length: MAX_GRID * MAX_GRID }).map((_, i) => {
          const r = Math.floor(i / MAX_GRID);
          const c = i % MAX_GRID;
          const active = hover && r <= hover.r && c <= hover.c;
          return (
            <div
              key={i}
              className="w-[18px] h-[18px] rounded-[3px] border transition-colors cursor-pointer"
              style={{
                borderColor: active ? '#6366f1' : '#e0e0e0',
                backgroundColor: active ? '#6366f140' : '#f5f5f5',
              }}
              onMouseEnter={() => setHover({ r, c })}
              onMouseDown={(e) => {
                e.stopPropagation();
                e.preventDefault();
                onSelect(r + 1, c + 1);
              }}
            />
          );
        })}
      </div>
      <div className="text-center text-[10px] text-muted-foreground mt-1.5 font-mono">
        {hover ? `${hover.r + 1} × ${hover.c + 1}` : 'hover to select size'}
      </div>
    </div>
  );
}

function TablePanel() {
  const { state, createNode, dispatch } = useCanvasStore();
  const [hoveredItem, setHoveredItem] = useState<string | null>(null);
  const [pickerAnchor, setPickerAnchor] = useState<{ top: number; left: number } | null>(null);
  const hoverTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  const addTable = useCallback((rows: number, cols: number, variant: TableVariant) => {
    const zoom = state.zoom;
    const cx = (-state.pan.x + window.innerWidth / 2) / zoom - 150;
    const cy = (-state.pan.y + window.innerHeight / 2) / zoom - 80;
    const td = makeTableData(rows, cols, variant);
    createNode(cx, cy, 'table_grid' as ShapeType, td);
    setHoveredItem(null);
    setPickerAnchor(null);
  }, [state.zoom, state.pan, createNode]);

  const handleItemMouseEnter = useCallback((variant: string, e: React.MouseEvent) => {
    if (variant === 'default') {
      const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
      if (hoverTimerRef.current) clearTimeout(hoverTimerRef.current);
      setHoveredItem(variant);
      setPickerAnchor({ top: rect.top, left: rect.right + 4 });
    } else {
      setHoveredItem(null);
      setPickerAnchor(null);
    }
  }, []);

  const handleItemMouseLeave = useCallback(() => {
    hoverTimerRef.current = setTimeout(() => {
      setHoveredItem(null);
      setPickerAnchor(null);
    }, 200);
  }, []);

  const handlePickerMouseEnter = useCallback(() => {
    if (hoverTimerRef.current) clearTimeout(hoverTimerRef.current);
  }, []);

  const handlePickerMouseLeave = useCallback(() => {
    hoverTimerRef.current = setTimeout(() => {
      setHoveredItem(null);
      setPickerAnchor(null);
    }, 150);
  }, []);

  return (
    <>
      <div ref={panelRef} className="w-52 bg-card border-r border-border py-2 overflow-y-auto">
        <CollapsibleSection title="tables" defaultOpen={true}>
