export default function Sidebar() {
  const { state, dispatch, createNode } = useCanvasStore();
  const [activePanel, setActivePanel] = useState<string | null>(null);
  const [polygonMenu, setPolygonMenu] = useState<{ x: number; y: number } | null>(null);
  const [polygonSides, setPolygonSides] = useState(6);
  const polygonMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!polygonMenu) return;
    const handler = (e: MouseEvent) => {
      if (polygonMenuRef.current && !polygonMenuRef.current.contains(e.target as Node)) {
        setPolygonMenu(null);
      }
    };
    window.addEventListener('mousedown', handler);
    return () => window.removeEventListener('mousedown', handler);
  }, [polygonMenu]);

  const addShape = (shape: ShapeType) => {
    const zoom = state.zoom;
    const cx = (-state.pan.x + window.innerWidth / 2) / zoom - 80;
    const cy = (-state.pan.y + window.innerHeight / 2) / zoom - 40;
    createNode(cx, cy, shape);
  };

  const addText = (type: 'text' | 'textbox') => {
    const zoom = state.zoom;
    const cx = (-state.pan.x + window.innerWidth / 2) / zoom - 80;
    const cy = (-state.pan.y + window.innerHeight / 2) / zoom - 20;
    createNode(cx, cy, type === 'textbox' ? 'text' : 'text');
    setActivePanel(null);
  };

  const handleClick = (id: string) => {
    if (id === 'annotate') {
      const isAnnotating = state.tool === 'annotate';
      dispatch({ type: 'SET_TOOL', tool: isAnnotating ? 'select' : 'annotate' as CanvasTool });
      setActivePanel(null);
      return;
    }
    setActivePanel(activePanel === id ? null : id);
  };

  const FlyoutPanel = ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div className="w-52 bg-card border-r border-border py-2 overflow-y-auto">
      <div className="px-3 py-1 text-[10px] uppercase tracking-wider text-muted-foreground">{title}</div>
      {children}
    </div>
  );

  // Entities grid sections
  const entitySections: GridSection[] = [
    {
      title: 'entities',
      defaultOpen: true,
      items: [
        { icon: <Link size={20} strokeWidth={1.5} />, label: 'hyperlink' },
        { icon: <LayoutGrid size={20} strokeWidth={1.5} />, label: 'widget' },
        { icon: <Layers size={20} strokeWidth={1.5} />, label: 'nested canvas' },
        { icon: <Globe size={20} strokeWidth={1.5} />, label: 'web embed' },
      ],
    },
  ];

  // Attach grid sections
  const attachSections: GridSection[] = [
    {
      title: 'file attachment',
      defaultOpen: true,
      items: [
        { icon: <FileText size={20} strokeWidth={1.5} />, label: 'document', hint: 'pdf, docx, word, epub, txt' },
        { icon: <Hash size={20} strokeWidth={1.5} />, label: 'tables', hint: 'csv, excel sheets' },
      ],
    },
    {
      title: 'media',
      defaultOpen: true,
      items: [
        { icon: <Image size={20} strokeWidth={1.5} />, label: 'photo embed', onClick: () => addShape('image_embed' as ShapeType) },
        { icon: <Video size={20} strokeWidth={1.5} />, label: 'video embed' },
        { icon: <Music size={20} strokeWidth={1.5} />, label: 'audio embed' },
      ],
    },
    {
      title: 'spatial thought',
      defaultOpen: true,
      items: [
        { icon: <Layers size={20} strokeWidth={1.5} />, label: 'nested canvas' },
        { icon: <Link size={20} strokeWidth={1.5} />, label: 'hyperlink' },
      ],
    },
  ];

  // Text grid sections
  const textItems: GridItem[] = [
    { icon: <Type size={20} strokeWidth={1.5} />, label: 'text node', onClick: () => addText('text') },
    { icon: <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="2" y="4" width="16" height="12" rx="1" /><line x1="5" y1="8" x2="15" y2="8" /><line x1="5" y1="11" x2="12" y2="11" /></svg>, label: 'text box', onClick: () => addText('textbox') },
  ];

  return (
    <div className="flex h-full">
      {/* Icon rail — flex-shrink items to fit without scroll */}
      <div className="w-[68px] bg-card border-r border-border flex flex-col items-center py-1 shrink-0">
        {SIDEBAR_ITEMS.map(item => {
          const Icon = item.icon;
          const isActive = item.id === 'annotate' ? state.tool === 'annotate' : activePanel === item.id;
          return (
            <button
              key={item.id}
              className={`w-full flex flex-col items-center justify-center gap-0.5 flex-1 min-h-0 transition-colors ${isActive ? 'bg-accent text-accent-foreground' : 'text-muted-foreground hover:bg-accent/50 hover:text-foreground'}`}
              onClick={() => handleClick(item.id)}
            >
              <Icon size={18} strokeWidth={1.4} />
              <span className="text-[9px] leading-none font-mono">{item.label}</span>
            </button>
          );
        })}
      </div>

      {/* Flyout panels */}
      {activePanel === 'shapes' && (
        <div className="w-52 bg-card border-r border-border py-2 overflow-y-auto relative">
          {SHAPE_SECTIONS.map(section => (
            <CollapsibleSection key={section.title} title={section.title} defaultOpen={section.defaultOpen}>
              {section.items.length === 0 ? (
                <p className="px-3 py-2 text-[10px] text-muted-foreground/60 italic">nothing here yet</p>
              ) : (
                <div className="grid grid-cols-2 gap-1.5 px-2 pb-2">
                  {section.items.map(s => (
                    <button
                      key={s.value}
                      className="flex flex-col items-center gap-1.5 py-3 px-2 rounded-lg border border-border/50 hover:bg-accent hover:border-border transition-all text-foreground"
                      onClick={() => {
                        if (s.value === 'polygon') {
                          const zoom = state.zoom;
                          const cx = (-state.pan.x + window.innerWidth / 2) / zoom - 80;
                          const cy = (-state.pan.y + window.innerHeight / 2) / zoom - 40;
                          const node = createNode(cx, cy, 'polygon');
                          dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { polygonEdges: polygonSides } });
                        } else {
                          addShape(s.value);
                        }
                      }}
                      onContextMenu={(e) => {
                        if (s.value === 'polygon') {
                          e.preventDefault();
                          e.stopPropagation();
                          setPolygonMenu({ x: e.clientX, y: e.clientY });
                        }
                      }}
                    >
                      <span className="text-muted-foreground">{s.icon}</span>
                      <span className="text-[9px] font-mono leading-none">{s.value === 'polygon' ? `polygon (${polygonSides})` : s.label}</span>
                    </button>
                  ))}
                </div>
              )}
            </CollapsibleSection>
          ))}

          {/* Polygon sides context menu */}
          {polygonMenu && (
            <div
              ref={polygonMenuRef}
              className="fixed z-[9999] bg-card border border-border rounded-lg shadow-lg py-2 px-3 min-w-[160px]"
              style={{ left: polygonMenu.x, top: polygonMenu.y }}
            >
              <div className="text-[10px] uppercase tracking-wider text-muted-foreground mb-2">polygon sides</div>
              <div className="flex items-center gap-2">
                <button
                  className="w-6 h-6 rounded border border-border flex items-center justify-center hover:bg-accent transition-colors disabled:opacity-30"
                  disabled={polygonSides <= 3}
                  onClick={() => setPolygonSides(Math.max(3, polygonSides - 1))}
                >
                  <Minus size={12} />
                </button>
                <span className="text-sm font-mono w-8 text-center">{polygonSides}</span>
                <button
                  className="w-6 h-6 rounded border border-border flex items-center justify-center hover:bg-accent transition-colors disabled:opacity-30"
                  disabled={polygonSides >= 12}
                  onClick={() => setPolygonSides(Math.min(12, polygonSides + 1))}
                >
                  <Plus size={12} />
                </button>
              </div>
              <div className="flex flex-wrap gap-1 mt-2">
                {[3, 4, 5, 6, 7, 8, 10, 12].map(n => (
                  <button
                    key={n}
                    className={`w-7 h-7 rounded text-[10px] font-mono border transition-colors ${polygonSides === n ? 'bg-primary text-primary-foreground border-primary' : 'border-border hover:bg-accent'}`}
                    onClick={() => { setPolygonSides(n); }}
                  >
                    {n}
                  </button>
                ))}
              </div>
              <button
                className="w-full mt-2 text-[10px] py-1 rounded bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
                onClick={() => {
                  setPolygonMenu(null);
                  const zoom = state.zoom;
                  const cx = (-state.pan.x + window.innerWidth / 2) / zoom - 60;
                  const cy = (-state.pan.y + window.innerHeight / 2) / zoom - 60;
                  const node = createNode(cx, cy, 'polygon');
                  dispatch({ type: 'UPDATE_NODE', id: node.id, updates: { polygonEdges: polygonSides } });
                }}
              >
                add {polygonSides}-sided polygon
              </button>
            </div>
          )}
        </div>
      )}

      {activePanel === 'text' && (
        <div className="w-52 bg-card border-r border-border py-2 overflow-y-auto">
          <div className="px-3 py-1 text-[10px] uppercase tracking-wider text-muted-foreground">text</div>
          <div className="grid grid-cols-2 gap-1.5 px-2 pb-2">
            {textItems.map((item, i) => (
              <GridCard key={i} {...item} />
            ))}
          </div>
        </div>
      )}

      {activePanel === 'diagrams' && (
        <FlyoutPanel title="diagrams">
          <p className="px-3 py-2 text-[11px] text-muted-foreground leading-relaxed">
            build flowcharts, mind maps, and tree diagrams using quickflow. select a node and click a directional arrow to chain nodes.
          </p>
        </FlyoutPanel>
      )}

      {activePanel === 'styles' && (
        <FlyoutPanel title="styles">
          <p className="px-3 py-2 text-[11px] text-muted-foreground leading-relaxed">
            right-click any node or connection to customize colors, borders, text styling, stroke types, and drawing style.
          </p>
        </FlyoutPanel>
      )}

      {activePanel === 'charts' && (
        <FlyoutPanel title="charts">
          <p className="px-3 py-2 text-[11px] text-muted-foreground leading-relaxed">chart embedding coming soon.</p>
        </FlyoutPanel>
      )}

      {activePanel === 'table' && <TablePanel />}

      {activePanel === 'entities' && <GridPanel sections={entitySections} />}
      {activePanel === 'attach' && <GridPanel sections={attachSections} />}

      {activePanel === 'presets' && (
        <FlyoutPanel title="presets">
          <p className="px-3 py-2 text-[11px] text-muted-foreground leading-relaxed">
            save and apply reusable node styles, shapes, and layout presets for consistent diagramming.
          </p>
