import { ChevronRight, ChevronDown } from 'lucide-react';
import { useState } from 'react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import type { CanvasNode } from '../types';

interface TreeItemProps {
  node: CanvasNode;
  nodes: CanvasNode[];
  edges: { fromNodeId: string; toNodeId: string }[];
  depth: number;
}

function TreeItem({ node, nodes, edges, depth }: TreeItemProps) {
  const { state, dispatch } = useCanvasStore();
  const [expanded, setExpanded] = useState(true);
  const isSelected = state.selectedNodeIds.includes(node.id);

  // Find children via edges (from this node -> other nodes)
  const childIds = edges.filter(e => e.fromNodeId === node.id).map(e => e.toNodeId);
  const children = childIds.map(id => nodes.find(n => n.id === id)).filter(Boolean) as CanvasNode[];
  const hasChildren = children.length > 0;

  return (
    <div>
      <div
        className={`flex items-center gap-1 py-0.5 px-1 cursor-pointer rounded text-[11px] transition-colors ${isSelected ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/50 text-foreground'}`}
        style={{ paddingLeft: depth * 14 + 4 }}
        onClick={() => dispatch({ type: 'SELECT_NODE', id: node.id })}
      >
        {hasChildren ? (
          <button
            className="p-0 shrink-0 text-muted-foreground hover:text-foreground"
            onClick={e => { e.stopPropagation(); setExpanded(!expanded); }}
          >
            {expanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
          </button>
        ) : (
          <span className="w-3 shrink-0" />
        )}
        <span
          className="w-2.5 h-2.5 rounded-sm shrink-0 border border-border"
          style={{ backgroundColor: node.style?.fillColor ?? '#F0F0F0' }}
        />
        <span className="truncate font-mono">{node.label || node.shape}</span>
      </div>
      {hasChildren && expanded && (
        <div>
          {children.map(child => (
            <TreeItem key={child.id} node={child} nodes={nodes} edges={edges} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
}

export default function StructureTree() {
  const { state } = useCanvasStore();

  // Find root nodes (not a target of any edge)
  const targetIds = new Set(state.edges.map(e => e.toNodeId));
  const roots = state.nodes.filter(n => !targetIds.has(n.id));
  const orphans = roots.length === 0 ? state.nodes : roots;

  if (state.nodes.length === 0) {
    return (
      <div className="px-3 py-3 text-[11px] text-muted-foreground font-mono">
        no nodes yet
      </div>
    );
  }

  return (
    <div className="py-1 max-h-64 overflow-y-auto">
      {orphans.map(node => (
        <TreeItem key={node.id} node={node} nodes={state.nodes} edges={state.edges} depth={0} />
      ))}
    </div>
  );
}

