      {icon}
      <span>{label}</span>
    </div>
  );
}

function Divider() {
  return <div className="h-px bg-border mx-1 my-0.5" />;
}

export default function TableContextMenu({ nodeId, position, contextCell, onClose }: Props) {
  const { state, dispatch } = useCanvasStore();
  const node = state.nodes.find(n => n.id === nodeId);
  if (!node || !node.tableData) return null;

  const td = node.tableData;
  const r = contextCell?.r ?? 0;
  const c = contextCell?.c ?? 0;

  const insertRowAbove = () => { dispatch({ type: 'TABLE_INSERT_ROW', id: nodeId, afterRow: r - 1 }); onClose(); };
  const insertRowBelow = () => { dispatch({ type: 'TABLE_INSERT_ROW', id: nodeId, afterRow: r }); onClose(); };
  const deleteRow = () => { dispatch({ type: 'TABLE_DELETE_ROW', id: nodeId, row: r }); onClose(); };
  const clearRow = () => { dispatch({ type: 'TABLE_CLEAR_ROW', id: nodeId, row: r }); onClose(); };

  const insertColLeft = () => { dispatch({ type: 'TABLE_INSERT_COL', id: nodeId, afterCol: c - 1 }); onClose(); };
  const insertColRight = () => { dispatch({ type: 'TABLE_INSERT_COL', id: nodeId, afterCol: c }); onClose(); };
  const deleteCol = () => { dispatch({ type: 'TABLE_DELETE_COL', id: nodeId, col: c }); onClose(); };
  const clearCol = () => { dispatch({ type: 'TABLE_CLEAR_COL', id: nodeId, col: c }); onClose(); };

  return (
    <div className="fixed inset-0 z-50" onClick={onClose}>
      <div className="absolute" style={{ left: position.x, top: position.y }} onClick={e => e.stopPropagation()}>
        <div className="w-56 border border-border rounded-md bg-card shadow-lg overflow-visible py-1">

          {/* Header showing context */}
          <div className="px-3 py-1 text-[10px] text-muted-foreground border-b border-border mb-0.5">
            table {td.rows}×{td.cols} · cell ({r + 1}, {c + 1})
          </div>

          {/* Row operations */}
          <SubMenu label={`row ${r + 1}`} icon={<Rows3 size={13} />}>
            <div className="w-48 border border-border rounded-md bg-card shadow-lg py-1">
              <MenuItem label="insert row above" icon={<Plus size={12} />} onClick={insertRowAbove} />
              <MenuItem label="insert row below" icon={<Plus size={12} />} onClick={insertRowBelow} />
              <Divider />
              <MenuItem label="clear row contents" icon={<Eraser size={12} />} onClick={clearRow} />
              {td.rows > 1 && (
                <MenuItem label="delete row" icon={<Trash2 size={12} />} onClick={deleteRow} danger />
              )}

              {/* Select entire row — highlights all cells */}
              <Divider />
              <div className="px-3 py-1 text-[10px] text-muted-foreground">
                row has {td.cols} cell{td.cols > 1 ? 's' : ''}
              </div>
            </div>
          </SubMenu>

          {/* Column operations */}
          <SubMenu label={`column ${c + 1}`} icon={<Columns3 size={13} />}>
            <div className="w-48 border border-border rounded-md bg-card shadow-lg py-1">
              <MenuItem label="insert column left" icon={<Plus size={12} />} onClick={insertColLeft} />
              <MenuItem label="insert column right" icon={<Plus size={12} />} onClick={insertColRight} />
              <Divider />
              <MenuItem label="clear column contents" icon={<Eraser size={12} />} onClick={clearCol} />
              {td.cols > 1 && (
                <MenuItem label="delete column" icon={<Trash2 size={12} />} onClick={deleteCol} danger />
              )}
              <Divider />
              <div className="px-3 py-1 text-[10px] text-muted-foreground">
                column has {td.rows} cell{td.rows > 1 ? 's' : ''}
              </div>
            </div>
          </SubMenu>

          <Divider />

          {/* Cell color */}
          <SubMenu label="cell color" icon={<Paintbrush size={13} />}>
            <CellColorPanel nodeId={nodeId} row={r} col={c} />
          </SubMenu>

          {/* Table padding */}
          <SubMenu label="table padding" icon={<Grid3X3 size={13} />}>
            <TablePaddingPanel nodeId={nodeId} />
          </SubMenu>

          {/* Border controls */}
          <SubMenu label="table border" icon={<Grid3X3 size={13} />}>
            <TableBorderPanel nodeId={nodeId} />
          </SubMenu>

          <Divider />

          {/* Toggle header */}
          <MenuItem
            label={td.hasHeader ? 'remove header row' : 'make first row header'}
            icon={<Rows3 size={13} />}
            onClick={() => {
              dispatch({ type: 'UPDATE_NODE', id: nodeId, updates: {
                tableData: { ...td, hasHeader: !td.hasHeader, variant: !td.hasHeader ? 'heading' : 'default' }
              }});
              onClose();
            }}
          />

          {/* Layering */}
          <div className="px-3 py-1.5 flex items-center justify-between text-xs">
            <span className="text-foreground">layering</span>
            <div className="flex gap-1">
              <button className="p-0.5 rounded hover:bg-accent" title="bring forward"
                onClick={() => dispatch({ type: 'BRING_FORWARD', id: nodeId })}>
                <ArrowUpToLine size={12} />
              </button>
              <button className="p-0.5 rounded hover:bg-accent" title="send backward"
                onClick={() => dispatch({ type: 'SEND_BACKWARD', id: nodeId })}>
                <ArrowDownToLine size={12} />
              </button>
            </div>
          </div>

          <Divider />

          {/* Delete table */}
          <MenuItem
            label="delete table"
            icon={<Trash2 size={13} />}
            onClick={() => { dispatch({ type: 'DELETE_NODE', id: nodeId }); onClose(); }}
            danger
          />
        </div>
      </div>
    </div>
  );
}

