import { useState, useRef, useEffect, useCallback } from 'react';
import type { TableData, NodeStyle } from '../types';
import { useCanvasStore } from '../hooks/useCanvasStore';

interface Props {
  nodeId: string;
  width: number;
  height: number;
  tableData: TableData;
  style: NodeStyle;
  isSelected: boolean;
  onCellContextMenu?: (r: number, c: number, e: React.MouseEvent) => void;
}

export default function TableNode({ nodeId, width, height, tableData, style, isSelected, onCellContextMenu }: Props) {
  const { dispatch } = useCanvasStore();
  const [editingCell, setEditingCell] = useState<{ r: number; c: number } | null>(null);
  const [selectedCells, setSelectedCells] = useState<Set<string>>(new Set());
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingCell && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [editingCell]);

  const { rows, cols, cells, hasHeader, variant } = tableData;
  const cellBgs = tableData.cellBgs;
  const cellW = width / cols;
  const cellH = height / rows;

  const handleCellClick = useCallback((r: number, c: number, e: React.MouseEvent) => {
    e.stopPropagation();
    const key = `${r}-${c}`;
    if (e.shiftKey || e.metaKey || e.ctrlKey) {
      setSelectedCells(prev => {
        const next = new Set(prev);
        if (next.has(key)) next.delete(key);
        else next.add(key);
        return next;
      });
    } else {
      setSelectedCells(new Set([key]));
    }
  }, []);

  const handleCellDoubleClick = useCallback((r: number, c: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingCell({ r, c });
    setSelectedCells(new Set([`${r}-${c}`]));
  }, []);

  const commitEdit = useCallback(() => {
    setEditingCell(null);
  }, []);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (!editingCell) return;
    if (e.key === 'Escape') {
      commitEdit();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      // Move down
      if (editingCell.r < rows - 1) {
        setEditingCell({ r: editingCell.r + 1, c: editingCell.c });
      } else {
        commitEdit();
      }
    } else if (e.key === 'Tab') {
      e.preventDefault();
      const nextC = e.shiftKey ? editingCell.c - 1 : editingCell.c + 1;
      if (nextC >= 0 && nextC < cols) {
        setEditingCell({ r: editingCell.r, c: nextC });
      } else if (!e.shiftKey && editingCell.r < rows - 1) {
        setEditingCell({ r: editingCell.r + 1, c: 0 });
      } else if (e.shiftKey && editingCell.r > 0) {
        setEditingCell({ r: editingCell.r - 1, c: cols - 1 });
      } else {
        commitEdit();
      }
    }
  }, [editingCell, cols, rows, commitEdit]);

  const isHeaderRow = (r: number) => hasHeader && r === 0;

  const getVariantStyles = () => {
    switch (variant) {
      case 'kanban':
        return { headerBg: '#e8d5f5', cellBg: '#fafafa', borderColor: '#e0d0e8' };
      case 'notion':
        return { headerBg: '#f0f0f0', cellBg: '#ffffff', borderColor: '#e5e5e5' };
      case 'calendar':
        return { headerBg: '#d4edff', cellBg: '#ffffff', borderColor: '#c8ddf0' };
      case 'timetable':
        return { headerBg: '#d5f5d5', cellBg: '#ffffff', borderColor: '#c8e8c8' };
      case 'heading':
        return { headerBg: '#eaeaea', cellBg: '#ffffff', borderColor: '#d5d5d5' };
      default:
        return { headerBg: 'transparent', cellBg: '#ffffff', borderColor: '#d5d5d5' };
    }
  };

  const vs = getVariantStyles();
  const pad = style.padding ?? 4;

  return (
    <div
      className="absolute inset-0"
      style={{ width, height, borderRadius: style.borderRadius ?? 4, overflow: 'hidden' }}
    >
      <table
        className="w-full h-full border-collapse"
        style={{
          tableLayout: 'fixed',
          border: `${style.borderWidth ?? 1}px ${style.borderStyle ?? 'solid'} ${vs.borderColor}`,
        }}
      >
        <tbody>
          {Array.from({ length: rows }).map((_, r) => (
            <tr key={r}>
              {Array.from({ length: cols }).map((_, c) => {
                const isHeader = isHeaderRow(r);
                const isEditing = editingCell?.r === r && editingCell?.c === c;
                const cellKey = `${r}-${c}`;
                const isCellSelected = selectedCells.has(cellKey);
                const value = cells[r]?.[c] ?? '';
                const customBg = cellBgs?.[cellKey];
                const defaultBg = isHeader ? vs.headerBg : vs.cellBg;

                return (
                  <td
                    key={c}
                    className="relative"
                    style={{
                      width: cellW,
                      height: cellH,
                      border: `1px solid ${vs.borderColor}`,
                      backgroundColor: customBg || defaultBg,
                      padding: 0,
                      fontWeight: isHeader ? 600 : 400,
                      fontSize: Math.min(style.fontSize ?? 12, 13),
                      verticalAlign: 'middle',
                    }}
                    onClick={(e) => handleCellClick(r, c, e)}
                    onDoubleClick={(e) => handleCellDoubleClick(r, c, e)}
                    onContextMenu={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      setSelectedCells(new Set([cellKey]));
                      onCellContextMenu?.(r, c, e);
                    }}
                  >
                    {isEditing ? (
                      <input
                        ref={inputRef}
                        className="w-full h-full border-none outline-none bg-transparent"
                        style={{
                          fontSize: Math.min(style.fontSize ?? 12, 13),
                          fontWeight: isHeader ? 600 : 400,
                          color: '#1a1a2e',
                          pointerEvents: 'auto',
                          padding: `0 ${pad}px`,
                        }}
                        value={value}
                        onChange={(e) => {
                          dispatch({ type: 'UPDATE_TABLE_CELL', id: nodeId, row: r, col: c, value: e.target.value });
                        }}
                        onBlur={commitEdit}
                        onKeyDown={handleKeyDown}
                        onMouseDown={(e) => e.stopPropagation()}
                      />
                    ) : (
                      <div
                        className="w-full h-full flex items-center select-none truncate"
                        style={{ color: '#333', pointerEvents: 'auto', cursor: 'text', padding: `0 ${pad}px` }}
                      >
                        {value}
                      </div>
                    )}

                    {/* Selection highlight */}
                    {isCellSelected && !isEditing && (
                      <div className="absolute inset-0 pointer-events-none" style={{
                        border: '2px solid #6366f1',
                        backgroundColor: '#6366f108',
                        zIndex: 2,
                      }} />
                    )}
                    {/* Editing ring */}
                    {isEditing && (
                      <div className="absolute inset-0 pointer-events-none" style={{
                        border: '2px solid #6366f1',
                        zIndex: 2,
                      }} />
                    )}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

