import { useState, useRef, useEffect, useCallback } from 'react';
import { Undo2, Redo2, Pencil, Eye, ChevronDown, ChevronRight, FileJson, Settings, FileDown, Upload, FileUp, Image as ImageIcon, FileImage, FileType, Copy, Check, Plus } from 'lucide-react';
import { useCanvasStore } from '../hooks/useCanvasStore';
import type { CanvasMode, CanvasBgPattern } from '../types';

interface Props {
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
}

const MODES: { value: CanvasMode; label: string; icon: typeof Pencil }[] = [
  { value: 'edit', label: 'edit mode', icon: Pencil },
  { value: 'preview', label: 'preview mode', icon: Eye },
];

const BG_COLORS = [
  '#ffffff',
  '#f5f0e8',
  '#fefce8',
  '#dcfce7',
  '#dbeafe',
  '#fce7f3',
  '#f472b6',
  '#ec4899',
  '#d4d4d4',
];

const PATTERNS: { value: CanvasBgPattern; label: string; isDefault?: boolean }[] = [
  { value: 'blank', label: 'blank' },
  { value: 'grid', label: 'gridded pattern' },
  { value: 'dotted', label: 'dotted', isDefault: true },
  { value: 'lined', label: 'lined' },
];

export default function TopBar({ onUndo, onRedo, canUndo, canRedo }: Props) {
  const { state, dispatch } = useCanvasStore();
  const [modeOpen, setModeOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [bgSubOpen, setBgSubOpen] = useState(false);
  const [customColorInput, setCustomColorInput] = useState('');
  const [showCustomColor, setShowCustomColor] = useState(false);
  const modeRef = useRef<HTMLDivElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!modeOpen) return;
    const handler = (e: MouseEvent) => {
      if (modeRef.current && !modeRef.current.contains(e.target as Node)) setModeOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [modeOpen]);

  useEffect(() => {
    if (!settingsOpen) return;
    const handler = (e: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) {
        setSettingsOpen(false);
        setBgSubOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [settingsOpen]);

  const currentMode = MODES.find(m => m.value === state.mode) || MODES[0];
  const ModeIcon = currentMode.icon;

  const handleExportJson = () => {
    const data = { nodes: state.nodes, edges: state.edges };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.boardTitle || 'flobo-canvas'}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setSettingsOpen(false);
  };

  const handleImportJson = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (ev) => {
        try {
          const data = JSON.parse(ev.target?.result as string);
          if (data.nodes && data.edges) {
            dispatch({ type: 'RESTORE', state: { ...state, nodes: data.nodes, edges: data.edges } });
          }
        } catch { /* ignore */ }
      };
      reader.readAsText(file);
    };
    input.click();
    setSettingsOpen(false);
  };

  // Canvas-to-SVG export
  const buildCanvasSvg = useCallback(() => {
    if (state.nodes.length === 0) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const n of state.nodes) {
      minX = Math.min(minX, n.x);
      minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x + n.width);
      maxY = Math.max(maxY, n.y + n.height);
    }
    const pad = 40;
    minX -= pad; minY -= pad; maxX += pad; maxY += pad;
    const w = maxX - minX;
    const h = maxY - minY;

    const rects = state.nodes.map(n => {
      const rx = n.shape === 'circle' || n.shape === 'oval' ? '50%' : `${n.style.borderRadius ?? 8}`;
      return `<g transform="translate(${n.x - minX}, ${n.y - minY})">
        <rect width="${n.width}" height="${n.height}" rx="${rx}" fill="${n.style.fillColor}" stroke="${n.style.borderColor}" stroke-width="${n.style.borderWidth}" opacity="${n.style.opacity}" />
        ${n.label ? `<text x="${n.width / 2}" y="${n.height / 2}" text-anchor="middle" dominant-baseline="central" font-size="${n.style.fontSize}" font-weight="${n.style.fontWeight}" fill="#1a1a2e">${n.label.replace(/&/g, '&amp;').replace(/</g, '&lt;')}</text>` : ''}
      </g>`;
    }).join('\n');

    return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
      <rect width="${w}" height="${h}" fill="${state.bgConfig.color}" />
      ${rects}
    </svg>`;
  }, [state.nodes, state.bgConfig.color]);

  const handleExportSvg = () => {
    const svg = buildCanvasSvg();
    if (!svg) return;
    const blob = new Blob([svg], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.boardTitle || 'flobo-canvas'}.svg`;
    a.click();
    URL.revokeObjectURL(url);
    setSettingsOpen(false);
  };

  const exportAsImage = useCallback(async (format: 'png' | 'pdf', transparent = false) => {
    const svg = buildCanvasSvg();
    if (!svg) return;
    // Parse SVG to get width/height
    const parser = new DOMParser();
    const doc = parser.parseFromString(svg, 'image/svg+xml');
    const svgEl = doc.documentElement;
    const w = parseFloat(svgEl.getAttribute('width') || '800');
    const h = parseFloat(svgEl.getAttribute('height') || '600');

    // If transparent, remove the background rect fill
    let svgStr = svg;
    if (transparent) {
      svgStr = svgStr.replace(/<rect width="[^"]*" height="[^"]*" fill="[^"]*" \/>/, (m) => m.replace(/fill="[^"]*"/, 'fill="none"'));
    }

    const img = new window.Image();
    const blob = new Blob([svgStr], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);

    return new Promise<void>((resolve) => {
      img.onload = () => {
        const scale = 2;
        const canvas = document.createElement('canvas');
        canvas.width = w * scale;
        canvas.height = h * scale;
        const ctx = canvas.getContext('2d')!;
        if (!transparent) {
          ctx.fillStyle = state.bgConfig.color;
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.scale(scale, scale);
        ctx.drawImage(img, 0, 0, w, h);
        URL.revokeObjectURL(url);

        if (format === 'png' || transparent) {
          canvas.toBlob((b) => {
            if (!b) return;
            if (transparent) {
              navigator.clipboard.write([new ClipboardItem({ 'image/png': b })]).catch(() => {
                // Fallback: download
                const dl = URL.createObjectURL(b);
                const a = document.createElement('a');
                a.href = dl; a.download = `${state.boardTitle || 'flobo-canvas'}-transparent.png`;
                a.click(); URL.revokeObjectURL(dl);
              });
            } else {
              const dl = URL.createObjectURL(b);
              const a = document.createElement('a');
              a.href = dl; a.download = `${state.boardTitle || 'flobo-canvas'}.png`;
              a.click(); URL.revokeObjectURL(dl);
            }
            resolve();
          }, 'image/png');
        } else {
          // PDF via print-style window
          const dataUrl = canvas.toDataURL('image/png');
          const win = window.open('', '_blank');
          if (win) {
            win.document.write(`<html><head><title>${state.boardTitle || 'flobo-canvas'}</title><style>@page{size:${w * scale}px ${h * scale}px;margin:0}body{margin:0;display:flex;justify-content:center;align-items:center}img{width:100%;height:auto}</style></head><body><img src="${dataUrl}" /></body></html>`);
            win.document.close();
            setTimeout(() => { win.print(); }, 500);
          }
          resolve();
        }
      };
      img.src = url;
    });
  }, [buildCanvasSvg, state.bgConfig.color, state.boardTitle]);

  const handleExportPng = async () => {
    await exportAsImage('png');
    setSettingsOpen(false);
  };

  const handleExportPdf = async () => {
    await exportAsImage('pdf');
    setSettingsOpen(false);
  };

  const handleCopyTransparent = async () => {
    await exportAsImage('png', true);
    setSettingsOpen(false);
  };

  const handleBgColorChange = (color: string) => {
    dispatch({ type: 'SET_BG_CONFIG', config: { color } });
    // Also switch to whiteboard to use bgConfig pattern rendering
    if (state.canvasBackground !== 'whiteboard') {
      dispatch({ type: 'SET_CANVAS_BACKGROUND', background: 'whiteboard' });
    }
  };

  const handlePatternChange = (pattern: CanvasBgPattern) => {
    dispatch({ type: 'SET_BG_CONFIG', config: { pattern } });
    if (state.canvasBackground !== 'whiteboard') {
      dispatch({ type: 'SET_CANVAS_BACKGROUND', background: 'whiteboard' });
    }
  };

  return (
    <div className="h-11 bg-card border-b border-border flex items-center justify-between px-4 shrink-0">
      {/* Left — logo + title */}
      <div className="flex items-center gap-2">
        <span className="font-semibold text-foreground tracking-tight text-sm">flobo</span>
        <span className="text-muted-foreground text-sm">·</span>
        <input
          className="text-sm text-muted-foreground bg-transparent border-none outline-none hover:text-foreground focus:text-foreground w-32 font-mono"
          value={state.boardTitle}
          onChange={e => dispatch({ type: 'SET_BOARD_TITLE', title: e.target.value })}
          onKeyDown={e => { if (e.key === 'Enter') (e.target as HTMLInputElement).blur(); }}
        />
      </div>

      {/* Center — undo/redo */}
      <div className="flex items-center gap-1">
        <button className="p-1.5 rounded hover:bg-accent transition-colors disabled:opacity-30 text-muted-foreground"
          disabled={!canUndo} onClick={onUndo}>
          <Undo2 size={15} strokeWidth={1.5} />
        </button>
        <button className="p-1.5 rounded hover:bg-accent transition-colors disabled:opacity-30 text-muted-foreground"
          disabled={!canRedo} onClick={onRedo}>
          <Redo2 size={15} strokeWidth={1.5} />
        </button>
      </div>

      {/* Right — settings gear + mode dropdown */}
      <div className="flex items-center gap-2">
        {/* Settings gear */}
        <div className="relative" ref={settingsRef}>
          <button
            className="p-1.5 rounded hover:bg-accent transition-colors text-muted-foreground"
            onClick={() => { setSettingsOpen(!settingsOpen); setBgSubOpen(false); }}
          >
            <Settings size={15} strokeWidth={1.5} />
          </button>
          {settingsOpen && (
            <div className="absolute right-0 top-full mt-1 bg-card border border-border rounded-lg shadow-lg overflow-visible z-50 min-w-[200px] py-1">
              {/* Import */}
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleImportJson}>
                <Upload size={13} className="text-muted-foreground shrink-0" />
                import json
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-muted-foreground transition-colors text-left cursor-default">
                <FileUp size={13} className="shrink-0" />
                <span>import svg <span className="text-[10px] opacity-60">— muted</span></span>
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-muted-foreground transition-colors text-left cursor-default">
                <FileUp size={13} className="shrink-0" />
                <span>import mermaid <span className="text-[10px] opacity-60">— muted</span></span>
              </button>

              <div className="h-px bg-border mx-2 my-1" />

              {/* Export */}
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleExportJson}>
                <FileJson size={13} className="text-muted-foreground shrink-0" />
                export json
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleExportSvg}>
                <FileImage size={13} className="text-muted-foreground shrink-0" />
                export svg
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleExportPng}>
                <ImageIcon size={13} className="text-muted-foreground shrink-0" />
                export png
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleExportPdf}>
                <FileType size={13} className="text-muted-foreground shrink-0" />
                export pdf
              </button>
              <button className="w-full flex items-center gap-2.5 px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left"
                onClick={handleCopyTransparent}>
                <Copy size={13} className="text-muted-foreground shrink-0" />
                copy transparent img
              </button>

              <div className="h-px bg-border mx-2 my-1" />

              {/* Change background — hover trigger */}
              <div
                className="relative"
                onMouseEnter={() => setBgSubOpen(true)}
                onMouseLeave={() => setBgSubOpen(false)}
              >
                <button className="w-full flex items-center justify-between px-3 py-1.5 text-xs hover:bg-accent/50 text-foreground transition-colors text-left">
                  <span className="flex items-center gap-2.5">
                    <span className="w-[13px] h-[13px] rounded-sm border border-border shrink-0" style={{ backgroundColor: state.bgConfig.color }} />
                    change background
                  </span>
                  <ChevronRight size={12} className="text-muted-foreground" />
                </button>

                {/* Sub-panel */}
                {bgSubOpen && (
                  <BackgroundSubMenu
                    bgConfig={state.bgConfig}
                    onPatternChange={handlePatternChange}
                    onColorChange={handleBgColorChange}
                    onLineColorChange={(lineColor) => dispatch({ type: 'SET_BG_CONFIG', config: { lineColor } })}
                    onGridSizeChange={(gridSize) => dispatch({ type: 'SET_BG_CONFIG', config: { gridSize } })}
                    customColorInput={customColorInput}
                    setCustomColorInput={setCustomColorInput}
                    showCustomColor={showCustomColor}
                    setShowCustomColor={setShowCustomColor}
                  />
                )}
              </div>
            </div>
          )}
        </div>

        {/* Mode dropdown */}
        <div className="relative" ref={modeRef}>
          <button
            className="flex items-center gap-1.5 bg-accent/60 rounded-md px-2.5 py-1 hover:bg-accent transition-colors"
            onClick={() => setModeOpen(!modeOpen)}
          >
            <ModeIcon size={12} className="text-muted-foreground" />
            <span className="text-xs text-foreground">{currentMode.label}</span>
            <ChevronDown size={10} className="text-muted-foreground" />
          </button>
          {modeOpen && (
            <div className="absolute right-0 top-full mt-1 bg-card border border-border rounded-md shadow-lg overflow-hidden z-50 min-w-[140px]">
              {MODES.map(m => {
                const Icon = m.icon;
                return (
                  <button
                    key={m.value}
                    className={`w-full flex items-center gap-2 px-3 py-1.5 text-xs transition-colors ${state.mode === m.value ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/50 text-foreground'}`}
                    onClick={() => { dispatch({ type: 'SET_MODE', mode: m.value }); setModeOpen(false); }}
                  >
                    <Icon size={12} className="text-muted-foreground" />
                    {m.label}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---- Background sub-menu panel ---- */

function BackgroundSubMenu({
  bgConfig,
  onPatternChange,
  onColorChange,
  onLineColorChange,
  onGridSizeChange,
  customColorInput,
  setCustomColorInput,
  showCustomColor,
  setShowCustomColor,
}: {
  bgConfig: { pattern: CanvasBgPattern; color: string; lineColor: string; gridSize: number };
  onPatternChange: (p: CanvasBgPattern) => void;
  onColorChange: (c: string) => void;
  onLineColorChange: (c: string) => void;
  onGridSizeChange: (s: number) => void;
  customColorInput: string;
  setCustomColorInput: (s: string) => void;
  showCustomColor: boolean;
  setShowCustomColor: (b: boolean) => void;
}) {
  return (
    <div
      className="absolute right-full top-0 mr-1 bg-card border border-border rounded-lg shadow-lg z-[60] py-2"
      style={{ width: 260 }}
    >
      {PATTERNS.map(p => {
        const isActive = bgConfig.pattern === p.value;
        return (
          <div key={p.value}>
            <button
              className={`w-full flex items-center justify-between px-3 py-2 text-left transition-colors ${isActive ? 'bg-accent/60' : 'hover:bg-accent/30'}`}
              onClick={() => onPatternChange(p.value)}
            >
              <span className="flex items-center gap-2">
                <span className="text-sm font-medium text-foreground">{p.label}</span>
                {p.isDefault && (
                  <span className="text-[9px] bg-primary/15 text-primary px-1.5 py-0.5 rounded-full font-mono">default</span>
                )}
              </span>
              {isActive && <Check size={16} className="text-green-500 shrink-0" />}
            </button>

            {/* Show color + grid controls when active and not blank */}
            {isActive && p.value !== 'blank' && (
              <div className="px-3 pb-2 pt-1 space-y-2.5">
                {/* Color circles for background */}
                <div className="flex items-center gap-1.5 flex-wrap">
                  {BG_COLORS.map(c => (
                    <button
                      key={c}
                      className="w-6 h-6 rounded-full border-2 transition-all shrink-0"
                      style={{
                        backgroundColor: c,
                        borderColor: bgConfig.color === c ? '#6366f1' : c === '#ffffff' ? '#d4d4d8' : 'transparent',
                        transform: bgConfig.color === c ? 'scale(1.15)' : 'scale(1)',
                      }}
                      onClick={() => onColorChange(c)}
                    />
                  ))}
                  {/* Custom hex color button */}
                  <div className="relative">
                    <button
                      className="w-6 h-6 rounded-full border-2 border-dashed border-border flex items-center justify-center text-muted-foreground hover:border-foreground hover:text-foreground transition-colors shrink-0"
                      onClick={() => setShowCustomColor(!showCustomColor)}
                    >
                      <Plus size={12} />
                    </button>
                    {showCustomColor && (
                      <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1.5 bg-card border border-border rounded-md shadow-lg p-2 z-10 min-w-[120px]">
                        <input
                          type="color"
                          value={customColorInput || bgConfig.color}
                          onChange={e => {
                            setCustomColorInput(e.target.value);
                            onColorChange(e.target.value);
                          }}
                          className="w-full h-7 rounded cursor-pointer border-0 p-0"
                        />
                        <input
                          className="w-full mt-1 text-[10px] font-mono bg-muted/50 border border-border rounded px-1.5 py-0.5 text-foreground outline-none"
                          placeholder="#hex"
                          value={customColorInput}
                          onChange={e => {
                            setCustomColorInput(e.target.value);
                            if (/^#[0-9a-fA-F]{6}$/.test(e.target.value)) {
                              onColorChange(e.target.value);
                            }
                          }}
                        />
                      </div>
                    )}
                  </div>
                </div>

                {/* Grid size slider */}
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground font-mono whitespace-nowrap">grid size</span>
                  <input
                    type="range"
                    min={12}
                    max={64}
                    value={bgConfig.gridSize}
                    onChange={e => onGridSizeChange(Number(e.target.value))}
                    className="flex-1 h-1 accent-muted-foreground"
                    style={{ accentColor: '#888' }}
                  />
                </div>
              </div>
            )}

            {/* Blank with just color circles */}
            {isActive && p.value === 'blank' && (
              <div className="px-3 pb-2 pt-1">
                <div className="flex items-center gap-1.5 flex-wrap">
                  {BG_COLORS.map(c => (
                    <button
                      key={c}
                      className="w-6 h-6 rounded-full border-2 transition-all shrink-0"
                      style={{
                        backgroundColor: c,
                        borderColor: bgConfig.color === c ? '#6366f1' : c === '#ffffff' ? '#d4d4d8' : 'transparent',
                        transform: bgConfig.color === c ? 'scale(1.15)' : 'scale(1)',
                      }}
                      onClick={() => onColorChange(c)}
                    />
                  ))}
                  <div className="relative">
                    <button
                      className="w-6 h-6 rounded-full border-2 border-dashed border-border flex items-center justify-center text-muted-foreground hover:border-foreground hover:text-foreground transition-colors shrink-0"
                      onClick={() => setShowCustomColor(!showCustomColor)}
                    >
                      <Plus size={12} />
                    </button>
                    {showCustomColor && (
                      <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1.5 bg-card border border-border rounded-md shadow-lg p-2 z-10 min-w-[120px]">
                        <input
                          type="color"
                          value={customColorInput || bgConfig.color}
                          onChange={e => {
                            setCustomColorInput(e.target.value);
                            onColorChange(e.target.value);
                          }}
                          className="w-full h-7 rounded cursor-pointer border-0 p-0"
                        />
                        <input
                          className="w-full mt-1 text-[10px] font-mono bg-muted/50 border border-border rounded px-1.5 py-0.5 text-foreground outline-none"
                          placeholder="#hex"
                          value={customColorInput}
                          onChange={e => {
                            setCustomColorInput(e.target.value);
                            if (/^#[0-9a-fA-F]{6}$/.test(e.target.value)) {
                              onColorChange(e.target.value);
                            }
                          }}
                        />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {/* Divider between patterns */}
            {p.value !== 'lined' && <div className="h-px bg-border mx-2 my-0.5" />}
          </div>
        );
      })}
    </div>
  );
}

