import { useState, useEffect } from 'react';
import { Plus, Minus } from 'lucide-react';
import { useCanvasStore } from '../hooks/useCanvasStore';

export default function ZoomOverlay() {
  const { state, dispatch } = useCanvasStore();
  const [showPct, setShowPct] = useState(false);
  const pct = Math.round(state.zoom * 100);

  useEffect(() => {
    setShowPct(true);
    const timer = setTimeout(() => setShowPct(false), 1200);
    return () => clearTimeout(timer);
  }, [pct]);

  return (
    <div
      className="absolute bottom-3 right-3 z-30 flex flex-col items-center gap-1"
      onMouseDown={e => e.stopPropagation()}
    >
      {/* Zoom in */}
      <button
        className="w-9 h-9 rounded-full bg-card border border-border shadow-sm flex items-center justify-center hover:bg-accent transition-colors text-foreground"
        onClick={() => dispatch({ type: 'SET_ZOOM', zoom: state.zoom + 0.1 })}
        title="zoom in"
      >
        <Plus size={16} strokeWidth={1.5} />
      </button>

      {/* Percentage — fades in/out */}
      <div className={`text-[10px] font-mono text-foreground bg-card border border-border rounded-full px-2 py-0.5 shadow-sm transition-opacity duration-300 ${showPct ? 'opacity-100' : 'opacity-0'}`}>
        {pct}%
      </div>

      {/* Zoom out */}
      <button
        className="w-9 h-9 rounded-full bg-card border border-border shadow-sm flex items-center justify-center hover:bg-accent transition-colors text-foreground"
        onClick={() => dispatch({ type: 'SET_ZOOM', zoom: state.zoom - 0.1 })}
        title="zoom out"
      >
        <Minus size={16} strokeWidth={1.5} />
      </button>
    </div>
  );
}

