import { Link } from 'react-router-dom';
import { ArrowLeft, ArrowRight, Square as LucideIcon } from 'lucide-react';
import PageLayout, { hand, serif } from '../PageLayout';

interface Section {
  title: string;
  body: React.ReactNode;
  subsections?: { title: string; body: React.ReactNode }[];
}

interface Props {
  tag: string;
  title: string;
  subtitle: string;
  sections: Section[];
  prev?: { label: string; href: string };
  next?: { label: string; href: string };
}

export default function FeatureSubpage({ tag, title, subtitle, sections, prev, next }: Props) {
  return (
    <PageLayout>
      <div className="max-w-3xl mx-auto px-6 py-16 md:py-24">
        <Link to="/features" className="inline-flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground mb-8 transition-colors">
          <ArrowLeft size={12} /> all features
        </Link>
        <p className="text-xs text-primary mb-3 tracking-wider uppercase" style={{ fontFamily: hand }}>{tag}</p>
        <h1 className="text-3xl md:text-5xl mb-4 tracking-tight" style={{ fontFamily: serif }}>{title}</h1>
        <p className="text-muted-foreground mb-14 max-w-lg leading-relaxed">{subtitle}</p>

        <div className="space-y-14">
          {sections.map((s, i) => (
            <section key={i}>
              <h2 className="text-xl mb-4 tracking-tight" style={{ fontFamily: serif }}>{s.title}</h2>
              <div className="text-sm text-muted-foreground leading-relaxed space-y-3">{s.body}</div>
              {s.subsections && (
                <div className="mt-8 space-y-8 pl-4 border-l-2 border-border/40">
                  {s.subsections.map((sub, j) => (
                    <div key={j}>
                      <h3 className="text-base mb-2 text-foreground/90" style={{ fontFamily: serif }}>{sub.title}</h3>
                      <div className="text-sm text-muted-foreground leading-relaxed space-y-3">{sub.body}</div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          ))}
        </div>

        {/* prev / next nav */}
        <div className="mt-16 pt-8 border-t border-border/40 flex items-center justify-between">
          {prev ? (
            <Link to={prev.href} className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1 transition-colors">
              <ArrowLeft size={12} /> {prev.label}
            </Link>
          ) : <span />}
          {next ? (
            <Link to={next.href} className="text-xs text-primary hover:text-primary/80 flex items-center gap-1 transition-colors">
              {next.label} <ArrowRight size={12} />
            </Link>
          ) : <span />}
        </div>
      </div>
    </PageLayout>
  );
}

