import { createContext, useContext, useReducer, useCallback, type ReactNode } from 'react';
import type { CanvasState, CanvasNode, CanvasEdge, ShapeType, NodeStyle, EdgeStyle, CanvasTool, CanvasMode, LayoutMode, LayoutDirection, CanvasBackground, CanvasDrawStyle, CanvasBgConfig, AnchorSide, TableData } from '../types';
import { DEFAULT_NODE_STYLE, DEFAULT_EDGE_STYLE } from '../types';
// canvas store — provides state, dispatch, and helper actions to all canvas components (v7)

let idCounter = 0;
const genId = () => `node_${++idCounter}_${Date.now()}`;
const genEdgeId = () => `edge_${++idCounter}_${Date.now()}`;
let zCounter = 1;

type Action =
  | { type: 'SELECT_NODE'; id: string | null }
  | { type: 'TOGGLE_SELECT_NODE'; id: string }
  | { type: 'SELECT_NODES'; ids: string[] }
  | { type: 'SELECT_EDGE'; id: string | null }
  | { type: 'ADD_NODE'; node: CanvasNode }
  | { type: 'UPDATE_NODE'; id: string; updates: Partial<CanvasNode> }
  | { type: 'UPDATE_NODE_STYLE'; id: string; style: Partial<NodeStyle> }
  | { type: 'DELETE_NODE'; id: string }
  | { type: 'ADD_EDGE'; edge: CanvasEdge }
  | { type: 'UPDATE_EDGE'; id: string; updates: Partial<CanvasEdge> }
  | { type: 'UPDATE_EDGE_STYLE'; id: string; style: Partial<EdgeStyle> }
  | { type: 'DELETE_EDGE'; id: string }
  | { type: 'SET_PAN'; pan: { x: number; y: number } }
  | { type: 'SET_ZOOM'; zoom: number }
  | { type: 'SET_EDITING'; id: string | null }
  | { type: 'SET_EDITING_EDGE'; id: string | null }
  | { type: 'SET_TOOL'; tool: CanvasTool }
  | { type: 'SET_MODE'; mode: CanvasMode }
  | { type: 'SET_LAYOUT_MODE'; mode: LayoutMode }
  | { type: 'SET_LAYOUT_DIRECTION'; direction: LayoutDirection }
  | { type: 'SET_CANVAS_BACKGROUND'; background: CanvasBackground }
  | { type: 'SET_CANVAS_DRAW_STYLE'; drawStyle: CanvasDrawStyle }
  | { type: 'SET_BG_CONFIG'; config: Partial<CanvasBgConfig> }
  | { type: 'SET_BOARD_TITLE'; title: string }
  | { type: 'AUTO_LAYOUT' }
  | { type: 'BRING_FORWARD'; id: string }
  | { type: 'SEND_BACKWARD'; id: string }
  | { type: 'UPDATE_TABLE_CELL'; id: string; row: number; col: number; value: string }
  | { type: 'TABLE_INSERT_ROW'; id: string; afterRow: number }
  | { type: 'TABLE_DELETE_ROW'; id: string; row: number }
  | { type: 'TABLE_INSERT_COL'; id: string; afterCol: number }
  | { type: 'TABLE_DELETE_COL'; id: string; col: number }
  | { type: 'TABLE_SET_CELL_BG'; id: string; row: number; col: number; color: string }
  | { type: 'TABLE_CLEAR_ROW'; id: string; row: number }
  | { type: 'TABLE_CLEAR_COL'; id: string; col: number }
  | { type: 'RESTORE'; state: CanvasState };

const initialState: CanvasState = {
  nodes: [],
  edges: [],
  selectedNodeId: null,
  selectedNodeIds: [],
  selectedEdgeId: null,
  pan: { x: 0, y: 0 },
  zoom: 1,
  editingNodeId: null,
  editingEdgeId: null,
  tool: 'select',
  mode: 'edit',
  layoutMode: 'custom',
  layoutDirection: 'topdown',
  canvasBackground: 'whiteboard',
  canvasDrawStyle: 'default',
  bgConfig: { pattern: 'dotted', color: '#ffffff', lineColor: '#c8c8c8', gridSize: 24 },
  boardTitle: 'untitled',
};

/* ---------- auto-layout helpers ---------- */

function computeTreeLayout(nodes: CanvasNode[], edges: CanvasEdge[], direction: LayoutDirection): CanvasNode[] {
  if (nodes.length === 0) return nodes;

  // Build adjacency from edges (from -> to)
  const childrenMap = new Map<string, string[]>();
  const hasParentEdge = new Set<string>();
  for (const e of edges) {
    const list = childrenMap.get(e.fromNodeId) || [];
    list.push(e.toNodeId);
    childrenMap.set(e.fromNodeId, list);
    hasParentEdge.add(e.toNodeId);
  }

  // Find roots
  const roots = nodes.filter(n => !hasParentEdge.has(n.id));
  if (roots.length === 0) return nodes; // cyclic, skip

  const nodeMap = new Map(nodes.map(n => [n.id, n]));
  const positioned = new Map<string, { x: number; y: number }>();
  const hGap = direction === 'topdown' ? 40 : 120;
  const vGap = direction === 'topdown' ? 120 : 40;

  // Compute subtree widths for spacing
  const subtreeSize = new Map<string, number>();
  function calcSize(id: string): number {
    if (subtreeSize.has(id)) return subtreeSize.get(id)!;
    const node = nodeMap.get(id);
    if (!node) { subtreeSize.set(id, 0); return 0; }
    const kids = childrenMap.get(id) || [];
    if (kids.length === 0) {
      const s = direction === 'topdown' ? node.width : node.height;
      subtreeSize.set(id, s);
      return s;
    }
    const total = kids.reduce((acc, kid) => acc + calcSize(kid) + hGap, -hGap);
    const s = Math.max(direction === 'topdown' ? node.width : node.height, total);
    subtreeSize.set(id, s);
    return s;
  }
  roots.forEach(r => calcSize(r.id));

  function layout(id: string, x: number, y: number) {
    positioned.set(id, { x, y });
    const kids = childrenMap.get(id) || [];
    if (kids.length === 0) return;
    const totalWidth = kids.reduce((acc, kid) => acc + (subtreeSize.get(kid) || 80) + hGap, -hGap);
    let offset = direction === 'topdown' ? x - totalWidth / 2 : y - totalWidth / 2;
    const node = nodeMap.get(id);
    const step = direction === 'topdown' ? (node?.height || 80) + vGap : (node?.width || 160) + vGap;
    for (const kid of kids) {
      const kidSize = subtreeSize.get(kid) || 80;
      const center = offset + kidSize / 2;
      if (direction === 'topdown') {
        layout(kid, center, y + step);
      } else {
        layout(kid, x + step, center);
      }
      offset += kidSize + hGap;
    }
  }

  let rootOffset = 0;
  for (const root of roots) {
    const size = subtreeSize.get(root.id) || 160;
    const center = rootOffset + size / 2;
    if (direction === 'topdown') {
      layout(root.id, center, 100);
    } else {
      layout(root.id, 100, center);
    }
    rootOffset += size + hGap * 2;
  }

  return nodes.map(n => {
    const pos = positioned.get(n.id);
    if (!pos) return n;
    return { ...n, x: pos.x - n.width / 2, y: pos.y - n.height / 2 };
  });
}

/* ---------- reducer ---------- */

function reducer(state: CanvasState, action: Action): CanvasState {
  switch (action.type) {
    case 'SELECT_NODE':
      return { ...state, selectedNodeId: action.id, selectedNodeIds: action.id ? [action.id] : [], selectedEdgeId: null };
    case 'TOGGLE_SELECT_NODE': {
      const ids = state.selectedNodeIds.includes(action.id)
        ? state.selectedNodeIds.filter(i => i !== action.id)
        : [...state.selectedNodeIds, action.id];
      return { ...state, selectedNodeIds: ids, selectedNodeId: ids.length === 1 ? ids[0] : (ids.length > 0 ? state.selectedNodeId : null), selectedEdgeId: null };
    }
    case 'SELECT_NODES':
      return { ...state, selectedNodeIds: action.ids, selectedNodeId: action.ids.length === 1 ? action.ids[0] : null, selectedEdgeId: null };
    case 'SELECT_EDGE':
      return { ...state, selectedEdgeId: action.id, selectedNodeId: null, selectedNodeIds: [] };
    case 'ADD_NODE':
      return { ...state, nodes: [...state.nodes, action.node] };
    case 'UPDATE_NODE':
      return { ...state, nodes: state.nodes.map(n => n.id === action.id ? { ...n, ...action.updates } : n) };
    case 'UPDATE_NODE_STYLE':
      return { ...state, nodes: state.nodes.map(n => n.id === action.id ? { ...n, style: { ...n.style, ...action.style } } : n) };
    case 'DELETE_NODE': {
      const edgesToRemove = state.edges.filter(e => e.fromNodeId === action.id || e.toNodeId === action.id);
      const edgeIds = new Set(edgesToRemove.map(e => e.id));
      return {
        ...state,
        nodes: state.nodes.filter(n => n.id !== action.id).map(n => ({
          ...n,
          childIds: n.childIds.filter(c => c !== action.id),
          parentId: n.parentId === action.id ? null : n.parentId,
        })),
        edges: state.edges.filter(e => !edgeIds.has(e.id)),
        selectedNodeId: state.selectedNodeId === action.id ? null : state.selectedNodeId,
        selectedNodeIds: state.selectedNodeIds.filter(i => i !== action.id),
      };
    }
    case 'ADD_EDGE':
      return { ...state, edges: [...state.edges, action.edge] };
    case 'UPDATE_EDGE':
      return { ...state, edges: state.edges.map(e => e.id === action.id ? { ...e, ...action.updates } : e) };
    case 'UPDATE_EDGE_STYLE':
      return { ...state, edges: state.edges.map(e => e.id === action.id ? { ...e, style: { ...e.style, ...action.style } } : e) };
    case 'DELETE_EDGE':
      return {
        ...state,
        edges: state.edges.filter(e => e.id !== action.id),
        selectedEdgeId: state.selectedEdgeId === action.id ? null : state.selectedEdgeId,
      };
    case 'SET_PAN':
      return { ...state, pan: action.pan };
    case 'SET_ZOOM':
      return { ...state, zoom: Math.max(0.1, Math.min(3, action.zoom)) };
    case 'SET_EDITING':
      return { ...state, editingNodeId: action.id };
    case 'SET_EDITING_EDGE':
      return { ...state, editingEdgeId: action.id };
    case 'SET_TOOL':
      return { ...state, tool: action.tool };
    case 'SET_MODE':
      return { ...state, mode: action.mode };
    case 'SET_LAYOUT_MODE':
      return { ...state, layoutMode: action.mode };
    case 'SET_LAYOUT_DIRECTION':
      return { ...state, layoutDirection: action.direction };
    case 'SET_CANVAS_BACKGROUND':
      return { ...state, canvasBackground: action.background };
    case 'SET_CANVAS_DRAW_STYLE':
      return { ...state, canvasDrawStyle: action.drawStyle };
    case 'SET_BG_CONFIG':
      return { ...state, bgConfig: { ...state.bgConfig, ...action.config } };
    case 'SET_BOARD_TITLE':
      return { ...state, boardTitle: action.title };
    case 'AUTO_LAYOUT': {
      const newNodes = computeTreeLayout(state.nodes, state.edges, state.layoutDirection);
      return { ...state, nodes: newNodes };
    }
    case 'BRING_FORWARD': {
      const maxZ = Math.max(...state.nodes.map(n => n.zIndex), 0);
      return { ...state, nodes: state.nodes.map(n => n.id === action.id ? { ...n, zIndex: maxZ + 1 } : n) };
    }
    case 'SEND_BACKWARD': {
      const minZ = Math.min(...state.nodes.map(n => n.zIndex), 0);
      return { ...state, nodes: state.nodes.map(n => n.id === action.id ? { ...n, zIndex: minZ - 1 } : n) };
    }
    case 'UPDATE_TABLE_CELL': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const newCells = n.tableData.cells.map((row, ri) =>
            ri === action.row ? row.map((cell, ci) => ci === action.col ? action.value : cell) : row
          );
          return { ...n, tableData: { ...n.tableData, cells: newCells } };
        }),
      };
    }
    case 'TABLE_INSERT_ROW': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const td = n.tableData;
          const newRow = Array(td.cols).fill('');
          const newCells = [...td.cells.slice(0, action.afterRow + 1), newRow, ...td.cells.slice(action.afterRow + 1)];
          const newH = n.height + (n.height / td.rows);
          return { ...n, height: newH, tableData: { ...td, rows: td.rows + 1, cells: newCells } };
        }),
      };
    }
    case 'TABLE_DELETE_ROW': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData || n.tableData.rows <= 1) return n;
          const td = n.tableData;
          const newCells = td.cells.filter((_, ri) => ri !== action.row);
          const newH = n.height - (n.height / td.rows);
          return { ...n, height: newH, tableData: { ...td, rows: td.rows - 1, cells: newCells } };
        }),
      };
    }
    case 'TABLE_INSERT_COL': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const td = n.tableData;
          const newCells = td.cells.map(row => [...row.slice(0, action.afterCol + 1), '', ...row.slice(action.afterCol + 1)]);
          const newW = n.width + (n.width / td.cols);
          return { ...n, width: newW, tableData: { ...td, cols: td.cols + 1, cells: newCells } };
        }),
      };
    }
    case 'TABLE_DELETE_COL': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData || n.tableData.cols <= 1) return n;
          const td = n.tableData;
          const newCells = td.cells.map(row => row.filter((_, ci) => ci !== action.col));
          const newW = n.width - (n.width / td.cols);
          return { ...n, width: newW, tableData: { ...td, cols: td.cols - 1, cells: newCells } };
        }),
      };
    }
    case 'TABLE_SET_CELL_BG': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const td = n.tableData;
          const cellBgs = { ...(td.cellBgs || {}) };
          cellBgs[`${action.row}-${action.col}`] = action.color;
          return { ...n, tableData: { ...td, cellBgs } };
        }),
      };
    }
    case 'TABLE_CLEAR_ROW': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const td = n.tableData;
          const newCells = td.cells.map((row, ri) => ri === action.row ? row.map(() => '') : row);
          return { ...n, tableData: { ...td, cells: newCells } };
        }),
      };
    }
    case 'TABLE_CLEAR_COL': {
      return {
        ...state,
        nodes: state.nodes.map(n => {
          if (n.id !== action.id || !n.tableData) return n;
          const td = n.tableData;
          const newCells = td.cells.map(row => row.map((cell, ci) => ci === action.col ? '' : cell));
          return { ...n, tableData: { ...td, cells: newCells } };
        }),
      };
    }
    case 'RESTORE':
      return action.state;
    default:
      return state;
  }
}

// Collect all descendant IDs of a collapsed node
function getCollapsedDescendants(nodes: CanvasNode[]): Set<string> {
  const hidden = new Set<string>();
  const collapsedParents = nodes.filter(n => n.collapsed);

  function collectChildren(parentId: string) {
    const parent = nodes.find(n => n.id === parentId);
    if (!parent) return;
    for (const childId of parent.childIds) {
      if (!hidden.has(childId)) {
        hidden.add(childId);
        collectChildren(childId);
      }
    }
  }

  for (const p of collapsedParents) {
    collectChildren(p.id);
  }
  return hidden;
}

interface StoreContextType {
  state: CanvasState;
  dispatch: React.Dispatch<Action>;
  createNode: (x: number, y: number, shape?: ShapeType, tableData?: TableData) => CanvasNode;
  createQuickFlowNode: (fromNodeId: string, direction: 'up' | 'down' | 'left' | 'right') => void;
  connectNodes: (fromNodeId: string, toNodeId: string) => void;
  getHiddenNodeIds: () => Set<string>;
}

const StoreContext = createContext<StoreContextType | null>(null);

export function CanvasStoreProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const createNode = useCallback((x: number, y: number, shape: ShapeType = 'rectangle', tableData?: TableData): CanvasNode => {
    let w = 160, h = 80;
    if (shape === 'polaroid') { w = 180; h = 220; }
    else if (shape === 'film_strip') { w = 120; h = 280; }
    else if (shape === 'photo_strip') { w = 140; h = 320; }
    else if (shape === 'receipt') { w = 160; h = 200; }
    else if (shape === 'sticky_note') { w = 160; h = 160; }
    else if (shape === 'square') { w = 120; h = 120; }
    else if (shape === 'circle') { w = 120; h = 120; }
    else if (shape === 'rhombus') { w = 120; h = 120; }
    else if (shape === 'trapezium') { w = 160; h = 100; }
    else if (shape === 'image_embed') { w = 240; h = 200; }
    else if (shape === 'table_grid') {
      const r = tableData?.rows ?? 4;
      const c = tableData?.cols ?? 4;
      w = Math.max(c * 100, 300);
      h = Math.max(r * 36, 120) + (tableData?.hasHeader ? 4 : 0);
    }
    const node: CanvasNode = {
      id: genId(),
      x, y,
      width: w,
      height: h,
      label: '',
      shape,
      polygonEdges: 6,
      style: { ...DEFAULT_NODE_STYLE },
      quickflowEnabled: true,
      collapsed: false,
      hyperlink: '',
      imageUrl: '',
      imageUrls: [],
      orientation: 'portrait',
      photoStripCount: 3,
      parentId: null,
      childIds: [],
      zIndex: ++zCounter,
      tableData: tableData || undefined,
    };
    dispatch({ type: 'ADD_NODE', node });
    dispatch({ type: 'SELECT_NODE', id: node.id });
    if (shape !== 'table_grid') {
      dispatch({ type: 'SET_EDITING', id: node.id });
    }
    return node;
  }, []);

  const createQuickFlowNode = useCallback((fromNodeId: string, direction: 'up' | 'down' | 'left' | 'right') => {
    const fromNode = state.nodes.find(n => n.id === fromNodeId);
    if (!fromNode) return;

    const gap = 60;
    let x = fromNode.x;
    let y = fromNode.y;

    if (direction === 'up') y = fromNode.y - fromNode.height - gap;
    else if (direction === 'down') y = fromNode.y + fromNode.height + gap;
    else if (direction === 'left') x = fromNode.x - fromNode.width - gap;
    else if (direction === 'right') x = fromNode.x + fromNode.width + gap;

    const newNode: CanvasNode = {
      id: genId(),
      x, y,
      width: fromNode.width,
      height: fromNode.height,
      label: '',
      shape: fromNode.shape,
      polygonEdges: fromNode.polygonEdges,
      style: { ...fromNode.style },
      quickflowEnabled: true,
      collapsed: false,
      hyperlink: '',
      imageUrl: '',
      imageUrls: [],
      orientation: fromNode.orientation || 'portrait',
      photoStripCount: fromNode.photoStripCount || 3,
      parentId: (direction === 'down' || direction === 'right') ? fromNodeId : null,
      childIds: [],
      zIndex: ++zCounter,
    };

    // Map quickflow direction to stable anchor sides
    const anchorMap: Record<string, { from: AnchorSide; to: AnchorSide }> = {
      up: { from: 'top', to: 'bottom' },
      down: { from: 'bottom', to: 'top' },
      left: { from: 'left', to: 'right' },
      right: { from: 'right', to: 'left' },
    };
    const anchors = anchorMap[direction];

    const edge: CanvasEdge = {
      id: genEdgeId(),
      fromNodeId: fromNodeId,
      toNodeId: newNode.id,
      style: { ...DEFAULT_EDGE_STYLE },
      freeForm: false,
      fromAnchor: anchors.from,
      toAnchor: anchors.to,
    };

    dispatch({ type: 'ADD_NODE', node: newNode });
    dispatch({ type: 'ADD_EDGE', edge });
    if (newNode.parentId) {
      dispatch({ type: 'UPDATE_NODE', id: fromNodeId, updates: { childIds: [...fromNode.childIds, newNode.id] } });
    }
    dispatch({ type: 'SELECT_NODE', id: newNode.id });
    dispatch({ type: 'SET_EDITING', id: newNode.id });
  }, [state.nodes]);

  const connectNodes = useCallback((fromNodeId: string, toNodeId: string) => {
    // Don't create duplicate edges
    const exists = state.edges.some(e =>
      (e.fromNodeId === fromNodeId && e.toNodeId === toNodeId) ||
      (e.fromNodeId === toNodeId && e.toNodeId === fromNodeId)
    );
    if (exists || fromNodeId === toNodeId) return;

    // Compute initial anchors based on relative positions
    const fromNode = state.nodes.find(n => n.id === fromNodeId);
    const toNode = state.nodes.find(n => n.id === toNodeId);
    let fromAnchor: AnchorSide = 'bottom';
    let toAnchor: AnchorSide = 'top';
    if (fromNode && toNode) {
      const dx = (toNode.x + toNode.width / 2) - (fromNode.x + fromNode.width / 2);
      const dy = (toNode.y + toNode.height / 2) - (fromNode.y + fromNode.height / 2);
      if (Math.abs(dy) >= Math.abs(dx)) {
        if (dy >= 0) { fromAnchor = 'bottom'; toAnchor = 'top'; }
        else { fromAnchor = 'top'; toAnchor = 'bottom'; }
      } else {
        if (dx >= 0) { fromAnchor = 'right'; toAnchor = 'left'; }
        else { fromAnchor = 'left'; toAnchor = 'right'; }
      }
    }

    const edge: CanvasEdge = {
      id: genEdgeId(),
      fromNodeId,
      toNodeId,
      style: { ...DEFAULT_EDGE_STYLE },
      freeForm: false,
      fromAnchor,
      toAnchor,
    };
    dispatch({ type: 'ADD_EDGE', edge });
  }, [state.edges, state.nodes]);

  const getHiddenNodeIds = useCallback(() => {
    return getCollapsedDescendants(state.nodes);
  }, [state.nodes]);

  return (
    <StoreContext.Provider value={{ state, dispatch, createNode, createQuickFlowNode, connectNodes, getHiddenNodeIds }}>
      {children}
    </StoreContext.Provider>
  );
}

export function useCanvasStore() {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error('useCanvasStore must be used within CanvasStoreProvider');
  return ctx;
}

